export default [{"id":123,"question":"سائل يقول: امرأة ضعيفة وكَلت مَن يرمي عنها في الحج، فهل لها أن تُغادر مكة صباح آخر يوم من أيام التَّشريق قبل موعد الرَّمي؟","title":"هل لمن وكّل للرمي عنه المغادرة قبل الرمي؟","answer":"الجواب: لا، ليس للمُوكِّل أن يُغادر حتى يطوف طواف الوداع بعد الرمي، فإذا رمى وكيله الجمرة الأخيرة يوم الثاني عشر أو الثالث عشر يطوف للوداع بعد ذلك، وليس له أن يُغادر حتى يطوف طواف الوداع بعد رمي الوكيل الجمار.\nفإذا كان الحاج مريضًا أو عاجزًا يُوكِّل، ولكن لا يُسافر حتى يطوف للوداع بعد رمي الوكيل لجميع الجمار.\nس: هل لها أن تُغادر مِنى قبل موعد الرمي إلى مكة؟\nالشيخ: العاجزة لها أن تُغادر، لكن ليس لها أن تُغادر حتى يرمي الوكيلُ، فلها أن تُغادر في الصباح قبل الظهر؛ لأنها ما ترمي بنفسها، بل يرمي وكيلها، أو العجوز، أو الكبير كذلك، لكن ليس له أن يُودِّع حتى يأتي الوكيلُ ويقول: رميتُ.","link":"https://binbaz.org.sa/fatwas/3621/هل-لمن-وكل-للرمي-عنه-المغادرة-قبل-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0108.mp3","categories":["رمي الجمار"]},{"id":407,"question":"لو أخَّرت الرمي لوجود الزحام إلى آخر يوم من أيام التشريق، ثم رميت الجمرات، فهل يُجزئ ذلك عني أم لا بدّ من دمٍ؟","title":"ما حكم تأجيل الرمي بسبب الزحام؟","answer":"الجواب: يُجزئ إن شاء الله؛ لأن الرسول أجاز للرعاة أن يُؤخِّروا بعض الأيام من أجل مشقَّة المجيء عليهم، فالزحام اليوم أعظم من مشقَّة الرعاة، كثرة الناس اليوم وكثرة الزحام فيه مشقَّة عظيمة، فالعلة التي من أجلها رخَّص للرعاة موجودة، فإذا أخَّر إلى اليوم الأخير فلا بأس، لكن يُرتب: يرمي يوم العيد بالترتيب، ثم يوم الحادي عشر، ثم الثاني عشر، ثم الثالث عشر -إذا أخَّر إلى الثالث عشر- بالترتيب. والأفضل إذا تيسر ألا يُؤخِّر شيئًا، فيرمي جمرة العقبة في يومها، ثم الحادي عشر كذلك، ثم الثالث عشر كذلك، ثم يتعجَّل إن شاء، هذا هو السُّنة مع القدرة.\nولو أخَّر حتى رمى بعد الغروب فلا بأس، لو شقَّ عليه يوم العيد -شقَّ عليه الرمي يوم العيد- فرمى بعد غروب الشمس من يوم العيد ليوم العيد فلا بأس، وهكذا لو رمى بعد غروب الشمس من الحادي عشر عن يوم الحادي عشر فلا بأس، وهكذا لو رمى في يوم الثاني عشر بعد الغروب عن رمي الثاني عشر؛ لعدم تيسر رميه بعد الزوال؛ فلا بأس على الصحيح؛ لأنه ليس هناك دليلٌ واضحٌ على إنهاء الرمي بغروب الشمس، أما اليوم الأخير فينتهي بغروب الشمس، فليلة الثالث عشر ليست من أيام الذبح والنحر، ولا من أيام الرمي، تنتهي أيام الرمي بغروب الشمس من يوم الثالث عشر.","link":"https://binbaz.org.sa/fatwas/4820/ما-حكم-تاجيل-الرمي-بسبب-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0465.mp3","categories":["رمي الجمار"]},{"id":611,"question":"هناك من يصل مِنى ثم لا يبدأ برمي الجمرات، ينتظر إلى العصر ثم يرمي؟","title":"ما حكم تأخير رمي الجمرات إلى العصر؟","answer":"الجواب: لا بأس، وإن رمى في الليل؛ أجزأ.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6450/ما-حكم-تاخير-رمي-الجمرات-الى-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/maram178.mp3","categories":["رمي الجمار"]},{"id":660,"question":"متى ينتهي وقت الرمي؟","title":"متى وقت انتهاء الرمي للحاج؟","answer":"الجواب: من غروب الشمس من يوم الثالث العشر، إذا غابت الشمس في اليوم الثالث عشر انتهى الرمي.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6691/متى-وقت-انتهاء-الرمي-للحاج","audio":"https://files.zadapps.info/binbaz.org.sa/maram229 - 03 - .mp3","categories":["رمي الجمار"]},{"id":665,"question":"النساء عند رمي الجمرات يسألون عن التوكيل، هل يقال لهن: ائتوا بالنساء في الليل؟","title":"ما حكم توكيل النساء في رمي الجمرات؟","answer":"الجواب: لا يجوز التوكيل إلا عند العجز، مريضة أو كبيرة في السن أو لديها أطفال ما تستطيع تركهم، أما الذي يخشى من الزحام يذهب في الليل.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6696/ما-حكم-توكيل-النساء-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/maram233 - 03 -  - 03 - .mp3","categories":["رمي الجمار"]},{"id":666,"question":"إذا شك في الرمي هل رمى خمسًا أو ستًّا؟","title":"حكم من شك في عدد حصيات الرمي","answer":"الجواب: يبني على اليقين ويجعلها خمسًا، وإذا شك: ست أو سبع؛ يجعلها ستًّا.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6701/حكم-من-شك-في-عدد-حصيات-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/maram234.mp3","categories":["رمي الجمار"]},{"id":1235,"question":"لو تركتُ رمي الجمار حتى آخر يومٍ، ما حكم ذلك؟","title":"هل يجوز ترك رمي الجمار إلى آخر يوم؟","answer":"الجواب:\nلا حرج إن شاء الله، لكنه خلاف السنة، ذكر جمعٌ من أهل العلم أنه لا حرج لو أخَّر لأجل الزحام، لكنه خلاف السنة، ينبغي أن يرمي في يوم العيد، كل يومٍ يرمي فيه رمية، ولو بالوكالة إذا كان عاجزًا، ولا يُؤخِّر، أو يرمي في الليل؛ لأنَّ الرمي في الليل على الصحيح جائزٌ.","link":"https://binbaz.org.sa/fatwas/21300/هل-يجوز-ترك-رمي-الجمار-الى-اخر-يوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1043هل يجوز ترك رمي الجمار إلى آخر يوم؟ ابن باز.mp3","categories":["رمي الجمار"]},{"id":1664,"question":"رمي الجمرات في آخر الليل وهو قادر هل يأثم؟","title":"حكم مَن رمى الجمرات آخر الليل دون عذر","answer":"الجواب:\nإن شاء الله ما يأثم، لكن في النهار أفضل كما رماها النبي ﷺ، أما إذا رماها في الليل فقد رمت أمُّ سلمة في الليل، ورمت أسماءُ بنت أبي بكر في الليل، فالأمر واسع إن شاء الله، لكن إذا تيسر الرمي في النهار يكون أفضل، كما رمى النبي في النهار، ورمى الصحابة في النهار، والرمي في الليل جائز على الصحيح.","link":"https://binbaz.org.sa/fatwas/21770/حكم-من-رمى-الجمرات-اخر-الليل-دون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من رمى الجمرات في آخر الليل.mp3","categories":["رمي الجمار"]},{"id":1666,"question":"أكثر النساء الآن يُوَكِّلْنَ مَن يرمي عنهن بحجة الزحام، يعني: ما يكون واجبًا؟","title":"حكم توكيل النساء في الرمي بسبب الزحام","answer":"الجواب:\nالمشروع أن يرمين بأنفسهن، إلا مَن عجزت: لكبر سنٍّ، أو مرضٍ، أو عندها أطفال، أو حامل وتخشى على نفسها، أو زحام شديد ما فيه حيلة؛ فهذا عذر شرعي، إذا تيسر التَّأخير إلى الليل ليكون أسلم من الزحام، رمي الحادي عشر، ورمي الثاني عشر في الغالب، إلا إذا كان في وسط الليل، أو أثناء الليل ما فيه زحام، كذلك يوم العيد لو شقَّ عليهنَّ وأخَّرن إلى ليلة أحد عشر لا حرج إن شاء الله، هذا هو الصحيح، وفيه خلاف بين أهل العلم، لكن هذا هو الصحيح.","link":"https://binbaz.org.sa/fatwas/21772/حكم-توكيل-النساء-في-الرمي-بسبب-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم توكيل النساء في الرمي بحجة الزحام.mp3","categories":["رمي الجمار"]},{"id":1734,"question":"إذا ذهب النساء والضُّعفاء في ليلة العيد متى يُشرع لهم رمي الجمرات؟","title":"متى يُشرع رمي الجمرات للنساء والضعفاء؟","answer":"الجواب:\nإذا وصلوا منى يرمون الجمرات: آخر الليل، أو أول الصبح، أو بعد طلوع الشمس، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/21841/متى-يشرع-رمي-الجمرات-للنساء-والضعفاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يشرع رمي الجمرات للنساء والضعفاء في ليلة العيد.mp3","categories":["رمي الجمار","قضايا المرأة"]},{"id":2705,"question":"رجل أخذ الحج عن امرأة وفي رمي الجمرات تذكر أنه ما رماها في الحوض، ماذا يفعل...؟","title":"حكم مَنْ رَمَى الجمرات ولم تقع في الحوض","answer":"الجواب: عليه دم، يُذْبَح في مكة للفقراء؛ لأن الرمي واجب من الواجبات، نَقْصٌ يُجْبَر بالدم.","link":"https://binbaz.org.sa/fatwas/22845/حكم-من-رمى-الجمرات-ولم-تقع-في-الحوض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رمى الجمرات ولم تقع في الحوض.mp3","categories":["رمي الجمار"]},{"id":3158,"question":"الرَّمْي: إذا جمع الإنسان يومي الحادي عشر والثاني عشر في الرمي، ثم أراد أن يرمي: هل يرمي كل جمرة لوحدها أو...؟","title":"حكم جَمْع الحادي والثاني عشر في الجمرات","answer":"الجواب: يبدأ بالحادي عشر يكمل، ثم يعود يرمي عن الثاني عشر، وهكذا الثالث عشر.\nس: ما يرمي كل جمرة عن الحادي عشر والثاني عشر؟\nالشيخ: لا لا، يُكمِل أوّل، يرمي الأولى والثانية والثالثة عن الحادي عشر، ثم يعود يرمي الأولى والثانية والثالثة عن الثاني عشر.\nس: ولكن إذا تَوَكَّل، إذا كان وكيلًا ...؟\nالشيخ: لا، الوكيل ما يخالف، يَرْمِي عَنْ نفسه وعَنْ مُوَكّله في الموقف عند كل جمرة.","link":"https://binbaz.org.sa/fatwas/23321/حكم-جمع-الحادي-والثاني-عشر-في-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جمع يومي الحادي عشر والثاني عشر في رمي الجمرات.mp3","categories":["رمي الجمار"]},{"id":3198,"question":"من أين التقط النبي ﷺ حصى الجِمار ما بين مزدلفة ومنى؟","title":"مِن أين التقط النبي ﷺ حصى الجِمار؟","answer":"الجواب: المعروف في الحديث أنه التقطها مِن مِنى، من أول مِنى، ضبط هذا ابن عباس: سبع حصيات مِن مِنى يوم العيد، والبقية مِن مِنى، كلها من مِنى، والأمر واسع في هذا.","link":"https://binbaz.org.sa/fatwas/23361/من-اين-التقط-النبي-ﷺ-حصى-الجمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أين التقط النبي حصى الجمار.mp3","categories":["رمي الجمار"]},{"id":4711,"question":"بالنسبة للمُرافق للضُّعفاء القوي؟","title":"حكم انصراف مرافق الضعفاء معهم آخر الليل","answer":"الجواب: نعم مثل الضُّعفاء، مَن كان معهم ينصرف معهم في آخر الليل، ويرمي معهم لا حرج.","link":"https://binbaz.org.sa/fatwas/25003/حكم-انصراف-مرافق-الضعفاء-معهم-اخر-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ينصرف مرافق الضعفاء القوي في آخر الليل.mp3","categories":["رمي الجمار"]},{"id":4714,"question":"رمي الأقوياء قبل طلوع الفجر؟","title":"هل يُجزئ رمي الأقوياء في الحج قبل الفجر؟","answer":"الجواب: يُجزئ لكن تركوا الأفضل، مَن رمى قبل طلوع الشمس أجزأ، لكن ترك الأفضل.","link":"https://binbaz.org.sa/fatwas/25006/هل-يجزى-رمي-الاقوياء-في-الحج-قبل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُجزئ رمي الأقوياء قبل طلوع الفجر.mp3","categories":["رمي الجمار"]},{"id":5162,"question":"سؤال ثانٍ يقول فيه: امرأة ضعيفة وكّلت مَن يرمي عنها في الحج، فهل لها أن تُغادر مكة صباح آخر يوم من أيام التَّشريق قبل موعد الرَّمي؟","title":"هل لمن وكَّل في الرمي أن يغادر قبل الرَّمي؟","answer":"الجواب: الشيخ: لا، ليس للمُوكِّل أن يُغادر حتى يطوف طواف الوداع بعد الرمي، فإذا رمى وكيله الجمرة الأخيرة يوم الثاني عشر أو الثالث عشر يطوف للوداع بعد ذلك، وليس له أن يُغادر حتى يطوف طواف الوداع بعد رمي الوكيل الجمار. فإذا كان الحاج مريضًا أو عاجزًا يُوكِّل، ولكن لا يُسافر حتى يطوف للوداع بعد رمي الوكيل لجميع الجمار. س: هل لها أن تُغادر منى قبل موعد الرمي إلى مكة؟ الشيخ: العاجزة لها أن تُغادر، لكن ليس لها أن تُغادر حتى يرمي الوكيلُ، فلها أن تُغادر في الصباح قبل الظهر؛ لأنها ما ترمي بنفسها، بل يرمي وكيلها، أو العجوز، أو الكبير كذلك، لكن ليس له أن يُودِّع حتى يأتي الوكيلُ ويقول: رميتُ.","link":"https://binbaz.org.sa/fatwas/30084/هل-لمن-وكل-في-الرمي-ان-يغادر-قبل-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 108.mp3","categories":["رمي الجمار"]},{"id":5217,"question":"يقول السائل: فضيلة الشيخ، هل يجوز للمرأة التَّوكيل عند رمي الجمار، حتى وإن لم تكن ضعيفةً؛ لأنها خشيت الزحام؟","title":"هل يجوز للمرأة التَّوكيل في الرمي خشية الزحام؟","answer":"الجواب: إن كان لها عذرٌ: كونها مريضة، أو حُبلى، أو هزيلة، أو يكون عندها أطفال ما تستطيع أن تُفارقهم، ما عندها مَن يحفظهم، ولا تستطيع أن تتركهم؛ فهذا عذرٌ، فتوكل، وإلا فعليها أن ترمي بنفسها في الأوقات المناسبة، مثل: بعد المغرب إذا كان يوم العيد زحمة: الظهر والعصر، ترمي بعد الغروب عن يوم العيد، معها زوجها، معها أخوها، معها أخواتها، وهكذا في بقية الأيام بعد الليل؛ لا بأس به، بعد الغروب إلى طلوع الفجر، كله رمي على الصَّحيح: في يوم العيد ليلة الحادي عشر عن يوم العيد، وليلة الاثني عشر عن يوم إحدى عشر، وليلة ثلاثة عشر عن يوم اثني عشر، أما يوم الثالث عشر فهذا ينتهي بغروب الشمس يوم الثالث عشر، فهو آخر أيام الرمي، ينتهي بغروب الشمس، فإذا شقَّ عليها الرمي في النهار بسبب الزحام؛ رمت بالليل والحمد لله.","link":"https://binbaz.org.sa/fatwas/30161/هل-يجوز-للمراة-التوكيل-في-الرمي-خشية-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatwa 194.mp3","categories":["رمي الجمار"]},{"id":6155,"question":"جاء في حديث ابن عباس قال: إني رميت بعدما أمسيت «قال: لا حرج» صححه البيهقي، فهل هذا صحيح أنه يجوز رمي جمرة العقبة بعد غروب شمس يوم النحر؟","title":"حكم رمي جمرة العقبة بعد غروب شمس يوم النحر","answer":"الجواب:  هذا جاء عن النبي ﷺ سئل يوم النحر، جاء في البخاري: أنه سئل يوم النحر، ما هو في أيام التشريق، سئل يوم النحر، قال له سائل: رميت بعدما أمسيت، يعني رمى في آخر النهار، فهذا مجزئ عند الجميع، إذا رمى آخر النهار مجزئ يوم العيد، أو رمى بعد الظهر، أو بعد العصر؛ لا بأس، ما هو معناه في الليل؛ لأنه سأله قبل أن يجيء الليل، رميت بعدما أمسيت إذا زالت الشمس، دخل المساء، فهذا معناه أنه رمى بعد الظهر، أو بعد العصر؛ فيجزئ ذلك.  وإن رمى بعد غروب الشمس فهذا محل خلاف بين أهل العلم، من أهل العلم من قال: إنه يجزئ، وهو قول جماعة من أهل العلم، وهو قول قوي. وقال آخرون: إذا غربت الشمس لا يجزئ، بل يؤجل، ويرمي بعد زوال الشمس قبل يوم الحادي عشر، يرمي جمرة العقبة في اليوم حادي عشر بعد الزوال، قبل أن يرمي جمرات الحادي عشر، هذا هو المشهور عند آخرون. وقال آخرون: يجزئ إذا رماها بعد الغروب، إذا فاته الرمي في النهار، ورمى بعد الغروب عن اليوم الماضي؛ أجزأ، وهو قول قوي، لا بأس به عند الحاجة. ولكن ينبغي للمؤمن أن يجتهد حتى يرمي في النهار كما رمى النبي ﷺ وكما رمى الصحابة -رضي الله عنهم وأرضاهم- في يوم العيد، وهكذا في الأيام التي بعده يرمي بعد الزوال قبل غروب الشمس، فإذا ضاقت عليه الأمور، وغابت الشمس، ولم يرم؛ أجزأه الرمي بعد الغروب في آخر الليل على الصحيح.","link":"https://binbaz.org.sa/fatwas/1607/حكم-رمي-جمرة-العقبة-بعد-غروب-شمس-يوم-النحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_501.mp3","categories":["رمي الجمار","المبيت بمنى"]},{"id":6156,"question":"جاء في حديث ابن عباس قال: إني رميت بعدما أمسيت «قال: لا حرج» صححه البيهقي، فهل هذا صحيح أنه يجوز رمي جمرة العقبة بعد غروب شمس يوم النحر؟","title":"حكم رمي جمرة العقبة بعد غروب شمس يوم النحر","answer":"الجواب:  هذا جاء عن النبي ﷺ سئل يوم النحر، جاء في البخاري: أنه سئل يوم النحر، ما هو في أيام التشريق، سئل يوم النحر، قال له سائل: رميت بعدما أمسيت، يعني رمى في آخر النهار، فهذا مجزئ عند الجميع، إذا رمى آخر النهار مجزئ يوم العيد، أو رمى بعد الظهر، أو بعد العصر؛ لا بأس، ما هو معناه في الليل؛ لأنه سأله قبل أن يجيء الليل، رميت بعدما أمسيت إذا زالت الشمس، دخل المساء، فهذا معناه أنه رمى بعد الظهر، أو بعد العصر؛ فيجزئ ذلك.  وإن رمى بعد غروب الشمس فهذا محل خلاف بين أهل العلم، من أهل العلم من قال: إنه يجزئ، وهو قول جماعة من أهل العلم، وهو قول قوي. وقال آخرون: إذا غربت الشمس لا يجزئ، بل يؤجل، ويرمي بعد زوال الشمس قبل يوم الحادي عشر، يرمي جمرة العقبة في اليوم حادي عشر بعد الزوال، قبل أن يرمي جمرات الحادي عشر، هذا هو المشهور عند آخرون. وقال آخرون: يجزئ إذا رماها بعد الغروب، إذا فاته الرمي في النهار، ورمى بعد الغروب عن اليوم الماضي؛ أجزأ، وهو قول قوي، لا بأس به عند الحاجة. ولكن ينبغي للمؤمن أن يجتهد حتى يرمي في النهار كما رمى النبي ﷺ وكما رمى الصحابة -رضي الله عنهم وأرضاهم- في يوم العيد، وهكذا في الأيام التي بعده يرمي بعد الزوال قبل غروب الشمس، فإذا ضاقت عليه الأمور، وغابت الشمس، ولم يرم؛ أجزأه الرمي بعد الغروب في آخر الليل على الصحيح.","link":"https://binbaz.org.sa/fatwas/1607/حكم-رمي-جمرة-العقبة-بعد-غروب-شمس-يوم-النحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_501.mp3","categories":["رمي الجمار","المبيت بمنى"]},{"id":6162,"question":"هل يجوز الرمي أيام التشريق في الليل بعد غروب الشمس؟ وهل الذي يرمي قبل الزوال عليه الإعادة بعد الزوال، أو مع اليوم الآخر؟","title":"حكم رمي الجمرات قبل الزوال وبعد غروب الشمس","answer":"الجواب:  الرمي في أيام التشريق بعد الزوال كما رمى النبي ﷺ ولا يجوز الرمي قبل الزوال في النهار، ومن رمى قبل الزوال؛ فعليه أن يعيد بعد الزوال، أما الرمي في الليل إذا غابت الشمس، أو في يوم العيد، وما رمى يوم العيد لمشاغل، أو مرض، أو ما أشبه ذلك، فاختلف العلماء، فمنهم من قال: يؤجلها حتى يرميها بعد الزوال في اليوم الحادي عشر قبل رمي اليوم الحادي عشر يبدأ بها بعد الزوال، قبل رمي اليوم الحادي عشر، ثم يعود إلى رمي الجمرات الثلاثة.. اليوم الحادي عشر. وقال بعض أهل العلم: يجوز أن يرميها بعد غروب الشمس في يوم العيد؛ لأنه ليس هناك دليل يمنع، الرسول ﷺ رمى بعد الزوال، ولم ينه عن الرمي بعد غروب الشمس، فرخص للرعاة أن يرموا بعد الغروب؛ لأنهم مشغولون في النهار بالرعي، فهذا يدل على أنه من شغل بالنهار، وحيل بينه وبين رمي النهار بسبب ازدحام شديد، أو بسبب أعمال أخرى؛ فإنه يرمي بعد الغروب، وهذا هو الأرجح والأقرب: أنه يجوز له الرمي بعد الغروب يوم العيد عن يوم العيد، وبعد غروب يوم الحادي عشر، عن يوم الحادي عشر، وبعد الغروب عن اليوم الثاني عشر، إذا لم يتيسر له الرمي في الثاني عشر، أما في الثالث عشر فلا، الثالث عشر ينتهي الرمي بالغروب ، فلا رمي بعد الغروب في اليوم الثالث عشر ، لكن رميه في النهار بعد الزوال أحوط، وأولى، وفيه خروج من الخلاف، والبعد عن الريبة.","link":"https://binbaz.org.sa/fatwas/1623/حكم-رمي-الجمرات-قبل-الزوال-وبعد-غروب-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_514.mp3","categories":["رمي الجمار","المبيت بمنى"]},{"id":6521,"question":"أصبت بضربة شمس بعد جمرة العقبة، وبعد طواف الإفاضة، ولم أتمكن من المبيت بمنى أيام التشريق لرمي الجمار، ووكلت في ذلك، فهل من دم؟ وإن كان فهل يصح في أي بلد آخر غير مكة؟","title":"حكم ترك المبيت بمنى لعذر والتوكيل في الرمي","answer":"الجواب:  ما دام ترك هذا بسبب المرض، والعجز عن المبيت في منى؛ فلا حرج في ذلك، من ترك المبيت في منى لمرض أصابه، ودخل في العلاج، أو أذن له من السقاة، أو من الرعاة، أو حارس، أو ما أشبه ذلك من الأعذار؛ فلا حرج عليه، والوكالة جائزة عند العذر.","link":"https://binbaz.org.sa/fatwas/2255/حكم-ترك-المبيت-بمنى-لعذر-والتوكيل-في-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_878.mp3","categories":["رمي الجمار","المبيت بمنى"]},{"id":6666,"question":"هل يجوز رمي الجمار في الليل في اليوم الحادي عشر، والثاني عشر، وإذا كان يجوز فأرجو أن يعلن هذا بين الناس في المنسك، وغيره؛ لأنه يحصل من الزحام ما تعلمون؟","title":"حكم رمي الجمار في الليل في الحادي عشر والثاني عشر","answer":"الجواب: الرمي في الليل يجوز على الصحيح من أقوال العلماء، فيه خلاف بين العلماء والمشهور عند أهل العلم أن الرمي يكون في النهار بعد الزوال إلى غروب الشمس في اليوم الحادي عشر، والثاني عشر، أما في يوم العيد فكله رمي، يوم العيد، وهكذا النصف الأخير من الليل .. في ليلة العيد للضعفاء، في آخر الليل، في النصف الأخير من الليل من العجزة، والنساء، وكبار السن، والمرضى، وأتباعهم، وأيام العيد كلها رمي. وأما يوم الحادي عشر، والثاني عشر فهذا مشهور عند العلماء أن الرمي ينتهي بغروب الشمس، ولا يجوز الرمي قبل الزوال، لا يجوز الرمي قبل الزوال أبدًا؛ لأن النبي ﷺ رمى بعد الزوال، وقال: خذوا عني مناسككم. واختلف العلماء هل يجوز الرمي بعد الغروب لمن لم يرم يوم العيد، ولمن لم يرم في اليوم الحادي عشر بعد الزوال؟ على قولين: أحدهما: يجوز، والثاني: لا يجوز، والأصح أنه يجوز، وقد بينا هذا غير مرة في أيام الحج، وإذا كان ما هو مبين في المنسك بيناه .. -إن شاء الله- إذا كان ما هو مبين يبين -إن شاء الله- في الطبعات الآتية، ولكن هو مبين.  فالحاصل: أن هذا هو الصواب، وهو الأرجح أنه يجوز الرمي بعد غروب الشمس لمن لم يرم نهارًا لليوم الذي غابت شمسه، ما هو لليوم الآتي، لليوم الذي غابت شمسه، فإذا غابت الشمس مثلًا يوم العيد، وهو مشغول ما رمى أو .. يرمي بعد الغروب على الصحيح، وقد بين ابن عمر هذا  سئل عن هذا وهذا. وهكذا يوم الحادي عشر لمن لم يتيسر له بسبب الزحام يرمي بعد غروب الشمس عن يوم الحادي عشر، وهكذا يوم الثاني عشر، زحم ولم يتيسر، أو شغل يرمي بعد الغروب إلى آخر الليل، يستمر إلى آخر الليل كله، رمي إلى آخر الليل، فإذا طلع الفجر أمسك إلى أن تزول الشمس. السؤال: الضعفاء جزاك الله خيرًا يكون له محرم مثلًا النساء؟ الجواب: الذي معهم محرمها معها يرمي معها، الذي مع الضعفاء يرمي معهم، ويطوف معهم في آخر الليل.","link":"https://binbaz.org.sa/fatwas/2541/حكم-رمي-الجمار-في-الليل-في-الحادي-عشر-والثاني-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1036.mp3","categories":["رمي الجمار"]},{"id":6674,"question":"من رمى في اليوم الحادي عشر في الليل، والثاني عشر قبل الغروب، هل يلزمه المبيت حتى يرمي في اليوم الثالث عشر؟","title":"حكم المبيت لمن رمى الجمار قبل الغروب في الثاني عشر","answer":"الجواب: لو خرج قبل الغروب في اليوم الثاني عشر لا يلزمه شيء، أما إذا تأخر حتى رمى بعد الغروب يبيت، يلزمه أن يبيت على الصحيح، الذي عليه جمهور أهل العلم يبيت، ويرمي في اليوم الثالث عشر بعد الزوال .. ما يكون فيه زحام، إذا رمى بعد الزوال ما يكون فيه زحام، والرمي ينتهي في اليوم الثالث عشر بغروب الشمس، إذا كانت غربت الشمس في اليوم الثالث عشر؛ انتهى الرمي بالإجماع، ما فيه خلاف. السؤال: إذا رمى بعد الغروب، ولم يبت عليه دم؟ الجواب: إذا رمى بعد الغروب، ولم يبت، إذا فدى، أو تصدق بشيء يكون أحسن، الدم فيه خلاف، لكن إذا تصدق بشيء يكون أحسن.","link":"https://binbaz.org.sa/fatwas/2542/حكم-المبيت-لمن-رمى-الجمار-قبل-الغروب-في-الثاني-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1037.mp3","categories":["رمي الجمار"]},{"id":6694,"question":"هل يجوز رمي الجمار في الليل في اليوم الحادي عشر، والثاني عشر، وإذا كان يجوز فأرجو أن يعلن هذا بين الناس في المنسك، وغيره؛ لأنه يحصل من الزحام ما تعلمون؟","title":"حكم رمي الجمار في الليل في الحادي عشر والثاني عشر","answer":"الجواب: الرمي في الليل يجوز على الصحيح من أقوال العلماء، فيه خلاف بين العلماء والمشهور عند أهل العلم أن الرمي يكون في النهار بعد الزوال إلى غروب الشمس في اليوم الحادي عشر، والثاني عشر، أما في يوم العيد فكله رمي، يوم العيد، وهكذا النصف الأخير من الليل .. في ليلة العيد للضعفاء، في آخر الليل، في النصف الأخير من الليل من العجزة، والنساء، وكبار السن، والمرضى، وأتباعهم، وأيام العيد كلها رمي. وأما يوم الحادي عشر، والثاني عشر فهذا مشهور عند العلماء أن الرمي ينتهي بغروب الشمس، ولا يجوز الرمي قبل الزوال، لا يجوز الرمي قبل الزوال أبدًا؛ لأن النبي ﷺ رمى بعد الزوال، وقال: خذوا عني مناسككم. واختلف العلماء هل يجوز الرمي بعد الغروب لمن لم يرم يوم العيد، ولمن لم يرم في اليوم الحادي عشر بعد الزوال؟ على قولين: أحدهما: يجوز، والثاني: لا يجوز، والأصح أنه يجوز، وقد بينا هذا غير مرة في أيام الحج، وإذا كان ما هو مبين في المنسك بيناه .. -إن شاء الله- إذا كان ما هو مبين يبين -إن شاء الله- في الطبعات الآتية، ولكن هو مبين.  فالحاصل: أن هذا هو الصواب، وهو الأرجح أنه يجوز الرمي بعد غروب الشمس لمن لم يرم نهارًا لليوم الذي غابت شمسه، ما هو لليوم الآتي، لليوم الذي غابت شمسه، فإذا غابت الشمس مثلًا يوم العيد، وهو مشغول ما رمى أو .. يرمي بعد الغروب على الصحيح، وقد بين ابن عمر هذا  سئل عن هذا وهذا. وهكذا يوم الحادي عشر لمن لم يتيسر له بسبب الزحام يرمي بعد غروب الشمس عن يوم الحادي عشر، وهكذا يوم الثاني عشر، زحم ولم يتيسر، أو شغل يرمي بعد الغروب إلى آخر الليل، يستمر إلى آخر الليل كله، رمي إلى آخر الليل، فإذا طلع الفجر أمسك إلى أن تزول الشمس. السؤال: الضعفاء جزاك الله خيرًا يكون له محرم مثلًا النساء؟ الجواب: الذي معهم محرمها معها يرمي معها، الذي مع الضعفاء يرمي معهم، ويطوف معهم في آخر الليل.","link":"https://binbaz.org.sa/fatwas/2541/حكم-رمي-الجمار-في-الليل-في-الحادي-عشر-والثاني-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1036.mp3","categories":["رمي الجمار"]},{"id":6698,"question":"هل يجوز رمي الجمار في الليل في اليوم الحادي عشر، والثاني عشر، وإذا كان يجوز فأرجو أن يعلن هذا بين الناس في المنسك، وغيره؛ لأنه يحصل من الزحام ما تعلمون؟","title":"حكم رمي الجمار في الليل في الحادي عشر والثاني عشر","answer":"الجواب: الرمي في الليل يجوز على الصحيح من أقوال العلماء، فيه خلاف بين العلماء والمشهور عند أهل العلم أن الرمي يكون في النهار بعد الزوال إلى غروب الشمس في اليوم الحادي عشر، والثاني عشر، أما في يوم العيد فكله رمي، يوم العيد، وهكذا النصف الأخير من الليل .. في ليلة العيد للضعفاء، في آخر الليل، في النصف الأخير من الليل من العجزة، والنساء، وكبار السن، والمرضى، وأتباعهم، وأيام العيد كلها رمي. وأما يوم الحادي عشر، والثاني عشر فهذا مشهور عند العلماء أن الرمي ينتهي بغروب الشمس، ولا يجوز الرمي قبل الزوال، لا يجوز الرمي قبل الزوال أبدًا؛ لأن النبي ﷺ رمى بعد الزوال، وقال: خذوا عني مناسككم. واختلف العلماء هل يجوز الرمي بعد الغروب لمن لم يرم يوم العيد، ولمن لم يرم في اليوم الحادي عشر بعد الزوال؟ على قولين: أحدهما: يجوز، والثاني: لا يجوز، والأصح أنه يجوز، وقد بينا هذا غير مرة في أيام الحج، وإذا كان ما هو مبين في المنسك بيناه .. -إن شاء الله- إذا كان ما هو مبين يبين -إن شاء الله- في الطبعات الآتية، ولكن هو مبين.  فالحاصل: أن هذا هو الصواب، وهو الأرجح أنه يجوز الرمي بعد غروب الشمس لمن لم يرم نهارًا لليوم الذي غابت شمسه، ما هو لليوم الآتي، لليوم الذي غابت شمسه، فإذا غابت الشمس مثلًا يوم العيد، وهو مشغول ما رمى أو .. يرمي بعد الغروب على الصحيح، وقد بين ابن عمر هذا  سئل عن هذا وهذا. وهكذا يوم الحادي عشر لمن لم يتيسر له بسبب الزحام يرمي بعد غروب الشمس عن يوم الحادي عشر، وهكذا يوم الثاني عشر، زحم ولم يتيسر، أو شغل يرمي بعد الغروب إلى آخر الليل، يستمر إلى آخر الليل كله، رمي إلى آخر الليل، فإذا طلع الفجر أمسك إلى أن تزول الشمس. السؤال: الضعفاء جزاك الله خيرًا يكون له محرم مثلًا النساء؟ الجواب: الذي معهم محرمها معها يرمي معها، الذي مع الضعفاء يرمي معهم، ويطوف معهم في آخر الليل.","link":"https://binbaz.org.sa/fatwas/2541/حكم-رمي-الجمار-في-الليل-في-الحادي-عشر-والثاني-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1036.mp3","categories":["رمي الجمار"]},{"id":7198,"question":"في حج هذا العام قمت برمي الجمرات في اليوم الثاني والثالث، مبتدئًا بالجمرة الكبيرة، ثم الوسطى، ثم الأولى، أي عكست الرمي، فهل علي هدي، أو فدي أفيدوني أفادكم الله؟","title":"حكم عكس الرمي في الحج","answer":"الجواب:\n\nلا ، هذه المسألة فيها خلاف بين أهل العلم، والسنة أن يبدأ بالتي في منى مما يلي مسجد الخيف كما بدأ بها النبي ﷺ، ثم ينزل ينزل مكة، فيرمي الوسطى، ثم الأخيرة التي هي جمرة العقبة التي رماها يوم العيد تكون هي الأخيرة في أيام التشريق، هذا هو السنة.\n\nلكن لو عكس يُعلم، إذا كان في وقت الرمي، لو عكس يعود ويرمي الوسطى، ثم الأخيرة حتى تكون بعد الأولى، لكن ما دام فات الوقت إن شاء الله يجزئه؛ لأن الخلاف مشهور، والأمر واسع -إن شاء الله- ما دام فات الوقت فقد رمى، والحمد لله.","link":"https://binbaz.org.sa/fatwas/3257/حكم-عكس-الرمي-في-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1586.mp3","categories":["رمي الجمار"]},{"id":7220,"question":"ذهبنا لرمي الجمرات في اليوم الثاني من أيام التشريق، ولكن مع شدة الزحام لم نتمكن من رؤية الجمرات، فكنت أنا ووالدي نرمي الحصى ولا ندري هل وقعت في الجمرات أم لا؟ مع أن غالب الظن أنها لم تصبها، فهل علينا شيء، علمًا بأنني قد سألت هذا السؤال شيخًا أثق بعلمه، وعدالته، فقال: عليكم دم، ولكني لم أتبين منه متى وكيف وأين؟ وأنا لم أقصد بإعادة السؤال على سماحتكم إلا البيان فقط، وزيادة الإيضاح؟","title":"حكم من لم يتيقن وصول الحصى في حوض الجمرات","answer":"الجواب: إذا كان الغالب على عملكم أنها لم تصل المرمى مثل ما قلت؛ فإن عليكم دم مثل ما أفتاكم الذي أفتاكم، إذا كنت يغلب على ظنك أن الحصى لم يصل الجمرات؛ فعليكم أن تفدوا عن ذلك ذبيحة، أنت عليك ذبيحة، وعن والدك ذبيحة؛ لأن رمي الجمرات واجب، فإذا لم يغلب الظن أنها وصلت، ولم تعلموا أنها وصلت؛ تذبحوا الذبيحة بالنية عن ذاك الحج الذي فعلتموه، عليك واحدة، وعلى أبيك واحدة، والفتوى التي قيلت لك فتوى صحيحة.","link":"https://binbaz.org.sa/fatwas/3287/حكم-من-لم-يتيقن-وصول-الحصى-في-حوض-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1612.mp3","categories":["رمي الجمار"]},{"id":7225,"question":"ذهبنا لرمي الجمرات في اليوم الثاني من أيام التشريق، ولكن مع شدة الزحام لم نتمكن من رؤية الجمرات، فكنت أنا ووالدي نرمي الحصى ولا ندري هل وقعت في الجمرات أم لا؟ مع أن غالب الظن أنها لم تصبها، فهل علينا شيء، علمًا بأنني قد سألت هذا السؤال شيخًا أثق بعلمه، وعدالته، فقال: عليكم دم، ولكني لم أتبين منه متى وكيف وأين؟ وأنا لم أقصد بإعادة السؤال على سماحتكم إلا البيان فقط، وزيادة الإيضاح؟","title":"حكم من لم يتيقن وصول الحصى في حوض الجمرات","answer":"الجواب: إذا كان الغالب على عملكم أنها لم تصل المرمى مثل ما قلت؛ فإن عليكم دم مثل ما أفتاكم الذي أفتاكم، إذا كنت يغلب على ظنك أن الحصى لم يصل الجمرات؛ فعليكم أن تفدوا عن ذلك ذبيحة، أنت عليك ذبيحة، وعن والدك ذبيحة؛ لأن رمي الجمرات واجب، فإذا لم يغلب الظن أنها وصلت، ولم تعلموا أنها وصلت؛ تذبحوا الذبيحة بالنية عن ذاك الحج الذي فعلتموه، عليك واحدة، وعلى أبيك واحدة، والفتوى التي قيلت لك فتوى صحيحة.","link":"https://binbaz.org.sa/fatwas/3287/حكم-من-لم-يتيقن-وصول-الحصى-في-حوض-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1612.mp3","categories":["رمي الجمار"]},{"id":7524,"question":"في الحقيقة لديهما سؤال آخر يقولان: هل يجوز التقاط جميع الجمرات من مزدلفة للجمرات الثلاث في الأيام الثلاثة أم لا يجوز؟","title":"حكم التقاط جميع الجمرات من مزدلفة","answer":"الجواب: التقاط الجمرات جائز من مزدلفة ومن بقية الحرم، ومن عادة العامة أنهم يلتقطون الحصى كلها من مزدلفة، وقد روي عن بعض السلف ذلك، ولكن الأفضل عدم ذلك، والرسول ﷺ إنما التقط سبعاً يوم العيد -صبيحة العيد- لقطها له ابن عباس وأعطاها إياه عليه الصلاة والسلام، وجعل يقبضها في يده ويقول: أمثال هؤلاء فارموا، وإياكم والغلو في الدين فإنما أهلك من كان قبلكم الغلو في الدين سبع، ما لقط إلا السبع، مثل حصى الخذف صغيرة، يعني مثل بعر الغنم غير الكبير، يعني بعر الغنم التي ليست بكبيرة، هذا هو حصى الخذف، فوق الحمص ودون البندق، يرمي به الجمرة يوم العيد وإن لقطه من منى كفى ذلك، فإن ظاهر الحديث أنه لقط له من منى عليه الصلاة والسلام، لقطه له صباح يوم العيد من منى ابن عباس ، هذا ظاهر السياق، فإذا لقطه من منى أو من مزدلفة فلا بأس، كله طيب وكله كافي، أما بقية الجمار فيلقط من منى، هذا ظاهر السنة، وإن لقطه من مزدلفة وجمعه فلا حرج، لكن الأفضل أن لا يتكلف، فيلقطه من منى ويكفيه والحمد لله، كل يوم واحد وعشرين حصاة من منى، للجمرات الثلاث الحادي عشر والثاني عشر، وهكذا الثالث عشر لمن لم يتعجل. نعم.\nومما قد يغلط فيه العامة: أنهم إذا وصلوا مزدلفة اشتغلوا بلقط الحصى قبل الصلاة وقبل كل شيء، هذا غلط ما لها أساس، إذا صلى وتفرغ وتعشى، إذا حب يلقطها لا بأس، وإن تركها بمنى كفى ذلك والحمد لله. المقصود: أن العامة يتكلفون في هذا وليس له أصل، إن لقطها من مزدلفة فلا بأس بعد ما يصلي وبعدما يستريح، وإن تركها حتى يلقطها من منى كفى ذلك، والحمد لله.","link":"https://binbaz.org.sa/fatwas/4498/حكم-التقاط-جميع-الجمرات-من-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_010/01002.mp3","categories":["رمي الجمار"]},{"id":7525,"question":"جزاكم الله خيراً، في الحقيقة هو كان سيسأل عن هذا السؤال أثابكم الله، سؤاله الرابع يقول فيه الأخوان: إذا نقصت الأحجار التي تؤخذ من مزدلفة لجمرة العقبة، هل يؤخذ لها من غير مزدلفة أم لا، وفقكم الله؟","title":"جواز أخذ الحصى من غير مزدلفة","answer":"الجواب: تقدم ما يدل على هذا، وأن أخذها من مزدلفة ما هو لازم شيء، لو أخذها من مزدلفة ونثرها وأخذ غيرها من منى كفى، فإذا أخذ من مزدلفة سبع ثم طاح منها شيء يأخذ من منى، الحمد لله، ولا حاجة إلى أن ينقلها معه ينثرها من منى يكفي.","link":"https://binbaz.org.sa/fatwas/4499/جواز-اخذ-الحصى-من-غير-مزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_010/01003.mp3","categories":["رمي الجمار"]},{"id":7842,"question":"سماحة الشيخ عبد العزيز ! هذه الرسالة وردتنا من حاج بنقالي يقول (م. ن. ج) بنقالي، يقول: إلى أصحاب الفضيلة المجيبين في إذاعة المملكة العربية السعودية وفقهم الله آمين، لقد كسرت حجر كبير إلى واحد وعشرين حجر ورميت به في اليوم الثاني أي في اليوم الأول من أيام التشريق، فهل يعتبر رميي هذا صحيحاً أم أنه يعتبر حجر واحد على حسب أصله، وفقكم الله؟","title":"حكم رمي الجمرات بحصيات مكسرة من حجر واحد","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالسنة والأفضل أن يلقط الإنسان حجر من الأرض من دون تكسير، يلقط حجرات من الأرض من دون تكسير؛ لأن التكسير قد يؤذيه، قد يضره، قد يطير إليه منه شيء، فإذا أخذه من الأرض فذلك أولى وأسلم وإذا كسره فلا حرج، إذا كسره من حجر كبير واستخرج من ذلك واحد وعشرين حصاة أو سبع حصيات أجزأه ذلك لابأس ولو مكسراً من حجر، فإذا رمى كل جمرة بسبع حصيات من هذا الحجر الكبير الذي كسره فإنه يجزي ولا بأس، ولكن ذكر العلماء أن كونه يلتقط الحجر الصغار من دون تكسير يكون أولى وأسلم وأبعد عن الخطر؛ لأنه قد يطير إليه شيء في التكسير وقد يضره، يضر عينه، يضر غير ذلك، هذا المقصود، وإلا فلا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5233/حكم-رمي-الجمرات-بحصيات-مكسرة-من-حجر-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_053/05301.mp3","categories":["رمي الجمار"]},{"id":7843,"question":"هذه رسالة من محمد صالح محمود يقول في رسالته وهي ذات شقين، يقول في الشق الأول: لم أتمكن من رمي جمرة العقبة يوم العيد، فرميتها ليلة اليوم الأول من أيام التشريق، فهل يلزمني شيء في ذلك أم لا، وفقكم الله؟","title":"حكم من فاته رمي جمرة العقبة يوم العيد","answer":"الجواب: الرمي يوم العيد مجزي كله؛ لأن يوم العيد كله محل رمي، لكن من فاته ذلك بأن غابت عليه الشمس يوم العيد ولم يرم ورمى بعد غروب الشمس أجزأه على الصحيح، كثير من أهل العلم يقولون لا يجزئه ولكن يؤجل الرمي إلى بعد الزوال من اليوم الحادي عشر فيبدأ به عن يوم العيد، ثم يرمي اليوم الحادي عشر، هكذا قال جماعة من أهل العلم وهو مشهور عند أهل العلم، ولكن الصواب أنه لا حرج في ذلك وأنه يجزئه إذا غابت الشمس ثم رمى بعد غروبها عن يوم العيد أجزأه على الصحيح، وإن أخره خروجاً من الخلاف ورماه بعد الزوال عن يوم العيد بالنية ثم رمى ذلك اليوم الحادي عشر بإحدى وعشرين حصاة عن ذلك اليوم بعد الزوال كان حسناً أيضاً وفيه خروج من الخلاف. نعم.","link":"https://binbaz.org.sa/fatwas/5234/حكم-من-فاته-رمي-جمرة-العقبة-يوم-العيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_053/05302.mp3","categories":["رمي الجمار"]},{"id":7845,"question":"هذه الرسالة وردتنا من المستمع شرف سعدون الشريف عراقي الجنسية، يقول: أنا حجيت بوالدتي، والتقطت لها جمار من مزدلفة لجميع الرمي، فطلبت مني غسل الجمار وتطييبها، وقلت لها: قد فعلت ذلك، وأنا كاذب؛ لأنه لا وقت عندي، فما حكم طلبها لغسل الجمار وتطييبها، وما حكم كذبي على أمي هل يقبل حجي أم لا؟","title":"حكم غسل حصيات الرمي وتطييبها","answer":"الجواب: أما غسل الجمار وتطييبها هذا لا أصل له، لا تغسل ولا تطيب الجمار، تؤخذ ويرمى بها بس؛ لأن النبي صلى الله عليه وسلم ما غسلها ولا طيبها عليه الصلاة والسلام، وهو المقتدى به، وهو الأسوة عليه الصلاة والسلام، وهو المشرع، فلا يستحب غسل الجمار ولا تطييبها، بل يرمى بها، تؤخذ من التراب ويرمى بها، هذا هو المشروع، وأما كونه قال لأمه -قلت لأمك أيها السائل- إنك فعلت وإنك غسلتها وطيبتها كاذباً فعليك التوبة إلى الله والاستغفار ولا تعد إلى مثل هذا، وحجك صحيح بحمد الله، لا يضر حجك هذا إنما هو نقص، نقص في الحج نقص في الدين الكذب، فعليك الاستغفار والتوبة، وكان الواجب عليك أن تقول لها: يا أمي! ما يستحب هذا، يا والدة! لا يستحب غسلها ولا تطييبها؛ لأن الرسول صلى الله عليه وسلم ما فعله ولا أصحابه، وعلينا أن نتأسى بهم، تعلمها بالسنة لأنها جاهلة تعلمها، لكن لعلك كنت جاهلاً أيضاً ما كنت تعرف بالسنة، فالحاصل أنه لا حرج عليك من جهة حجك، حجك صحيح وعليك التوبة والاستغفار عن كذبك، وعليك أن تعلم أن غسل الجمار وتطييبها لا يستحب ولا يشرع بل هو بدعة، فعليك أن تعلم الناس، تعلم إخوانك وجماعتك اللي معك في أي حج حججت وفي أي مجلس تقول لهم: هذا الشيء لا يشرع، وهكذا أرجو من سمع هذا المقال وهذا البرنامج أرجو منه إذا سمع الفائدة أن يبلغها غيره، وصيتي لإخواني المستمعين أن يبلغوا ما يسمعوا من الفائدة؛ لأن العلم هكذا يكون بالتبليغ، النبي عليه السلام إذا خطب الناس يقول لهم: فليبلغ الشاهد الغائب فرب مبلغ أوعى من سامع وكان يقول: بلغوا عني ولو آية عليه، عليه الصلاة والسلام، فعلينا -أيها الإخوة- أن نبلغ العلم، وأن نتواصى بالحق، وأن نتعاون على البر والتقوى حتى ينتشر العلم، إذا أنت نقلت الفائدة، والآخر نقل الفائدة، والأخرى -المرأة- نقلت الفائدة لأخواتها ولأقاربها، والأخرى نقلت اتسع العلم وكثر، فأنا وصيتي للمستمعين دائماً أن ينقلوا العلم إذا سمعوه من هذا البرنامج -أو غيره- نور على الدرب، إذا سمعوا الفائدة من أهل العلم ينشرونها في مجالسهم، وفي أحاديثهم بينهم، حتى يعم العلم، سواء كان ذلك يتعلق بالعقيدة والإخلاص لله سبحانه وتعالى والحذر من الشرك، أو كان يتعلق بالصلاة أو بالصيام أو بالحج أو بالمعاملات، على كل حال تبليغ العلم مطلوب لا من الرجال ولا من النساء، عليكم جميعاً أيها المستمعون رجالاً ونساءً أن تبلغوا ما تسمعوا من الفائدة في كل مكان تستطيعونه، رزق الله الجميع التوفيق والهداية. نعم.","link":"https://binbaz.org.sa/fatwas/5236/حكم-غسل-حصيات-الرمي-وتطييبها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_053/05304.mp3","categories":["رمي الجمار"]},{"id":8027,"question":"هذه رسالة وردت من المستمع محمود الروشدة من أبها، يسأل عن رمي الجمار في يوم العيد واليوم الأول من أيام التشريق، يقول: السادة المشرفين على برنامج نور على الدرب! السلام عليكم ورحمة الله وبركاته، أرجو التكرم من فضيلتكم بعرض سؤالي هذا على سماحة الشيخ عبد العزيز ليتكرم بدراسة موضوعي وإعطائي الحل المناسب وهو أنني قمت بأداء فريضة الحج في عامنا هذا المنصرم مع زملاء لي حجوا أكثر من مرة، والذي حصل أننا قمنا برمي الجمرات في يومين فقط، أي لم نبق في مكة بعد اليوم الأول من أيام العيد إلا يوم واحد، وفي اليوم الثاني بعد الظهر خرجنا من مكة على أساس أننا تعجلنا في يومين على اعتبار اليومين. اليوم الأول الذي هو العيد واليوم الثاني من أيام العيد، أرجو التكرم بإفتائنا في ذلك، ولكم الشكر وما يجب علي من القيام بعمل بالرغم أنني بعيد عن مكة كثيراً وشكراً لكم؟","title":"حكم من تعجل بعد رمي الجمار يوم العيد والذي بعده","answer":"الجواب: الذي خرج من مكة في حجه في العام الماضي أو غيره ولم يرم الجمار إلا في يوم العيد واليوم الذي يليه عليه دم، ذبيحة كالضحية، يعني: إما أن يذبح ضأن أو ثني معز أو سبع بدنة، أو سبع بقرة في مكة تذبح في مكة، وتوزع بين الفقراء -فقراء مكة-، هذا هو الذي عليه؛ لأن الواجب أن يرمي يوم العيد ويومين بعده، والأيام التي فيها التعجل هي أيام التشريق ثلاثة التي قال الله فيها سبحانه: فَمَنْ تَعَجَّلَ فِي يَوْمَيْنِ فَلا إِثْمَ عَلَيْهِ وَمَنْ تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ [البقرة:203] هذه أيام التشريق أولها الحادي عشر، وآخرها الثالث عشر، أما يوم العيد فليس منها، فالواجب على الحجاج أن يرموا يوم العيد جمرة العقبة، والأفضل في الضحى، ومن رماها في آخر الليل من ليلة العيد أو في الظهر من يوم العيد أو في العصر أجزأ كله رمي، في النصف الأخير من العيد ولا سيما الضعفاء، ويوم العيد كله رمي أما يوم الحادي عشر، والثاني عشر، والثالث عشر، فهذه ترمى فيها الجمار بعد الزوال، يعني: بعد دخول وقت الظهر إذا زالت الشمس ودخل وقت الظهر يرمي الحجاج الجمار، ولا يجوز أن يرموها قبل الزوال قبل الظهر، إنما الرمي يكون بعد الزوال كما رماها النبي عليه الصلاة والسلام، وإذا أحب التعجل في اليوم الثاني عشر بعد الرمي يرمي بعد الزوال ثم يتعجل ويذهب إلى مكة يطوف طواف الوداع، هذا لا بأس، وليس يوم العيد منها، بل أولها الحادي عشر، وآخرها الثالث العشر، فإذا رمى الحادي عشر والثاني عشر فلا بأس أن يتعجل فيذهب إلى مكة ويطوف طواف الوداع أو طواف الحج إن كان ما طاف طواف الحج ويجزيه عن طواف الوداع، إذا طاف طواف الحج بعد رمي الجمار وخرج إلى بلاده، سافر في الحال أجزأه عن طواف الوادع، وإن طاف طواف الحج يوم العيد أو بعده ثم طاف طواف الوداع عند خروجه فهذا أكمل وأفضل، والذي خرج في اليوم الثاني عشر أو في آخر اليوم الحادي عشر ولم يرم إلا يوم العيد واليوم الذي بعده فقط، يظن أن يوم العيد هو أحد الأيام الثلاثة فقد غلط، وعليه دم كما تقدم؛ لأنه ترك بعض الواجب وهو الرمي في اليوم الثاني عشر. نعم.\nالمقدم: لكن ألا يدخل هذا في قول الرسول ﷺ: غفر لأمتي الخطأ والنسيان؟\nالشيخ: لا، هذا ترك الواجبات مو بداخل عند العلماء، ترك الواجبات ما يدخل بهذا، هذاك في المحظورات، أما هذا ما يدخل فيه، وإذا كان ما بات ليلة اثنا عشر في منى وهو قادر فعليه أيضاً عن هذا دم أو صدقة، إذا كان ليلة الاثنا عشر ما بات في منى بات في مكة وهو قادر، عنده منزل في منى يستطيع فهذا ينبغي أن يتصدق بشيء أو يفدي عن ذلك، لأن المبيت بمنى واجب مع القدرة.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5635/حكم-من-تعجل-بعد-رمي-الجمار-يوم-العيد-والذي-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_078/07807.mp3","categories":["رمي الجمار"]},{"id":8197,"question":"هذه بعث بها أو هذه الرسالة وردتنا من ضواحي الدوادمي من عبد الله العتيبي ، وخص بالسؤال فضيلتكم يقول فيه: أفيدكم بأنني حجيت أول حج الفريضة، وعندما أتيت لرمي الجمرات اليوم الثاني، رميت في مرجم واحد، في موقف واحد، وعندما انتهت الحصيات التي معي، الاثنتين كررت وأخذت من الحصى الذي تحت رجل الناس في طرف المرجم، ورجمت به في المواقف الأخرى، أفيدونا جزاكم الله عنا خير الجزاء، ماذا علي؟ وماذا أفعل حيث رميتها ناسياً ولكم جزيل السلام؟","title":"حكم الرمي بالحصيات الموجودة قرب الجمرات","answer":"الجواب: لا بأس إن شاء الله تجزي، إذا رمى الإنسان من الجمرات الموجودة في الطريق، أو تحت أقدام الناس يجزي إن شاء الله، أما إذا أخذها من بعيد يكون أحوط وأحسن، وإلا فهو مجزي؛ لأن الأصل أنه لم يرم بها، قد تكون سقطت من الناس، قد تكون رمى بها إنسان ولم تصب، فالحاصل أنه ليس هناك جزم بأنه قد رمي بها، بل محتملة فهي مجزئة، ثم القول بأن ما رمي به لا يجزي قول عن اجتهاد وليس عن نص عن النبي عليه الصلاة والسلام، فتوقي الذي قد رمي به هذا لا شك أنه أولى لا يرمي به، أما شيء تحت أقدام الناس، فهذا لا يقطع أنه قد رمي به، فهو مجزي على كل حال، والرمي به إن شاء الله قد وقع في محله، وأما إذا كان في الاختيار فالأولى به أن يأخذ حجراً بعيد عن المراجم في المواضع البعيدة عن المراجم، حتى يكون أبعد عن كونه قد رمي به، هذا هو الأحوط والأحسن.\nالمقدم: لكن لو أخذ من تحت أرجل الناس هذا ........ ؟\nالشيخ: يجزي إن شاء الله يجزي وليس مقطوعاً بأنه قد رمي به. نعم.\nالمقدم: كثير من طلبة العلم ينهى الناس نهياً شديداً عن ذلك؟\nالشيخ: هذا ليس بجيد، ليس بجيد، لا ينبغي التشديد في هذا. نعم.","link":"https://binbaz.org.sa/fatwas/6011/حكم-الرمي-بالحصيات-الموجودة-قرب-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_094/09405.mp3","categories":["رمي الجمار"]},{"id":8608,"question":"يقول أيضاً: إذا كان الحاج رمى في اليوم الأخير الجمرة الوسطى حصاتين معاً والجمرة الأخيرة حصاتين معاً، هل عليه فدية أم فديتان؟","title":"حكم ترك رمي الجمرات أو بعضاً منها","answer":"الجواب: فدية واحدة، الرمي كله لا يوجب إلا فدية واحدة، فإذا ترك الرمي كله أو ترك بعضه، إذا ترك رمية جمرة واحدة من الجمرات الثلاث، أو ترك رمي يوم كامل كله ليس فيه إلا فدية واحدة، يتداخل بعضه في بعض، لكن ذكر العلماء أنه إذا كان المتروك حصاة واحدة أو حصاتين من الجمرة الأخيرة فإنه يعفى عنها عند جمع من أهل العلم، وإن ترك ثلاثاً لم يعف عن ذلك بل يكمل، فإن فات الوقت فعليه دم، وبكل حال فالجمار تتداخل فإذا تركه كله أو ترك رمي يوم من أيام التشريق غير اليوم الثالث، بأن ترك رمي الحادي عشر أو الثاني عشر، أو ترك جمرة واحدة يعني: سبع حصيات أو أربع حصيات أو خمس حصيات أو ثلاث حصيات فإن عليه دم. نعم.\nيلاحظ في مسألة الرمي أن الدم إنما يجب عند فوات الوقت، أما ما دام الوقت موجوداً فإنه يتمم، لكن لو كان فات الوقت بأن انتهت أيام منى ولم ينتبه إلا بعد ذلك فهذا هو محل الدم، أما لو نبه في أيام التشريق فإنه يرجع ويكمل ما فاته. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6739/حكم-ترك-رمي-الجمرات-او-بعضا-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21005.mp3","categories":["رمي الجمار"]},{"id":8731,"question":"رسالة وصلت إلى البرنامج من أختنا أم أحمد عبده من تعز، أختنا رسالتها مطولة بعض الشيء وتقول فيها: إني أضع مشكلتي هذه التي سببت لي القلق والحيرة آملة عدم إهمال الرد على مشكلتي وهي: ذهبت إلى الحج وقد خرجت من بيتي ومعي أربع نساء من الحي مع إخوانهن وكذلك كان ابني برفقتي من بيتي إلى المطار إلى أن وصلت إلى جماعة النساء واللائي كان معهن إخوانهن، واستقبلني زوجي في المطار وبعد ذلك قمنا بالبدء بأداء شعائر الحج، وحل وقت العيد ورميت الجمرات يوم العيد وثاني العيد وكلت زوجي، وثالث العيد قلت لزوجي: أريد أن أرمي الجمرات فمانع لشدة الزحام، وعلى إثر ذلك وقع بيننا شيء من الخصام فلم أوكله ولم أرم الجمرة ولم أطف أيضًا طواف الوداع نتيجة ما حصل بيننا، والآن أنا قلقة على ذلك النقص الذي حصل مني، أرجو أن توجهوني جزاكم الله خيرا؟","title":"حكم من حج وترك رمي الجمرات وطواف الوداع","answer":"الجواب: الحج صحيح والحمد لله، ولكن عليك فديتان:\nإحداهما: عن ترك الرمي تذبح في مكة ذبيحة من الغنم كالضحية؛ إما جذع ضأن أو ثني معز تذبح في الحرم في مكة وتوزع بين الفقراء.\nوالفدية الثانية: عن طواف الوداع؛ لأنك سافرت ولم تودعي، وظاهر كلامك أنك سافرت بدون محرم من بلدك إلى مطار جدة، وأن ابنك معك إلى المطار ثم تلقاك زوجك في المطار في جدة، وأنت معك نسوة، وهذا إن كان صحيحًا ما ظهر من سؤالك هو لا يجوز، ليس للمرأة أن تسافر إلا مع ذي محرم، ولو أن معها من يصحبها إلى المطار ويتلقاها في المطار؛ الرسول عليه السلام قال: لا تسافر امرأة إلا مع ذي محرم فإن كان هذا هو الواقع وأنك سافرت بدون محرم فعليك التوبة إلى الله والاستغفار وعدم العود إلى مثل هذا، والحج صحيح والحمد لله، وعليك ما ذكرنا من الفديتين: ذبيحة عن ترك الرمي، وذبيحة أخرى عن ترك الوداع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6882/حكم-من-حج-وترك-رمي-الجمرات-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_161/16104.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":8741,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضَمَّنها مجموعة من الأسئلة وهو فضل ياسين محمد فضل سوداني ومقيم في المملكة، أخونا في سؤاله الأول يقول: هل المسلم إذا قام بأداء الحج ووقف بعرفة وانحدر إلى مزدلفة، هل ضروري أن يلتقط حصى الجمرات من مزدلفة، أم يجوز من أي مكان من منى؟ لأني قرأت كتيبًا صغيرًا للمؤلف زيد بن مبارك ... مكتوب فيه أن الرسول ﷺ لم يحدد موقعًا معينًا، نرجو الإفتاء جزاكم الله خيرًا.","title":"تحديد المكان الذي تؤخذ منه الجمرات عند الرمي","answer":"الجواب: وهو كما قرأت، لا يتعين أن يلتقط الحصى من مزدلفة، بل يأخذه من منى ويكفي، والنبي لقطه من منى عليه الصلاة والسلام، ومن أخذه من مزدلفة، أو أخذ سبعًا من مزدلفة ليرمي بها جمرة العقبة يوم العيد فلا بأس، ولكن ليس بمتعين بل من مزدلفة أو من منى، كله بحمد الله واسع. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6895/تحديد-المكان-الذي-توخذ-منه-الجمرات-عند-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_162/16206.mp3","categories":["رمي الجمار"]},{"id":8828,"question":"هناك بعض الأسئلة -سماحة الشيخ- أرجو أيضًا أن تتفضلوا بالإجابة عليها حول الحج: ما هو الأولى للمرأة أن توكل من يرمي عنها في النهار إذا كانت لا تستطيع الرمي، أو أن ترمي ليلًا بنفسها؟","title":"الأولى للمرأة في رمي الجمرات","answer":"الجواب: الذي يظهر -والله أعلم- أن توكيلها أولى؛ لأن وقوع الرمي في النهار أفضل بكل حال؛ ولأنه قد يحصل بعض الزحام في الليل إذا تعالم الناس واعتادوا الرمي في الليل قد يصعب الأمر أيضًا، فتوكيلها حتى تؤدي العبادة في وقتها الأفضل أولى إن شاء الله؛ لكونها مثلًا عاجزة ما تستطيع الدخول مع الناس في الرمي، أو لكونها حبلى تخشى على حملها، أو لأسباب أخرى، توكيلها أولى. نعم.","link":"https://binbaz.org.sa/fatwas/6983/الاولى-للمراة-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_164/16404.mp3","categories":["رمي الجمار"]},{"id":8829,"question":"في هذا الوقت يكثر الزحام في الحج ويحصل أضرار عظيمة، فهل يجوز للحاج أن يؤخر الرمي حتى اليوم الثالث عشر ويرمي عن الأيام الماضية؟","title":"حكم تأخير رمي الجمرات إلى اليوم الثالث عشر","answer":"الجواب: أجاز هذا جمع من أهل العلم، وأنه لا بأس؛ واحتجوا أن النبي ﷺ قال للرعاة : أن يؤخروا اليوم الحادي عشر ويرموه مع الثاني عشر، قالوا: هذا جنس تأخير لعذر الرعاة، وإذا كان الرعاة يعذرون بسبب الإبل رعاية الإبل فكون الإنسان يعذر بسبب خوفه على نفسه الهلكة أولى وأولى، فنفس الإنسان أغلى وأرفع من نفس الإبل، فإذا كانت الرعاية للإبل ومصلحة الإبل ومصلحة الحجيج من أجل إبلهم تجعل الرعاة يرمون ليلًا ويرمون متأخرين فخوف الإنسان على نفسه من باب أولى أن يكون عذرًا؛ ولهذا أجاز جمع من أهل العلم أن يؤخر الرمي إلى اليوم الثاني عشر أو الثالث عشر ثم يرمي الحاج بالترتيب، يبدأ بيوم العيد ثم الحادي عشر ثم الثاني عشر ثم الثالث عشر إن تأخر عنه، كل هذا لا حرج فيه إن شاء الله ولا بأس.\nوهكذا كون الإنسان يوكل في الرمي لعجزه وضعفه وخشيته على نفسه كل هذا من باب رعاية المصالح العامة، ودفع الضرر العظيم؛ لأن قاعدة الشريعة: دفع الضرر، لا ضرر ولا ضرار، ورعاية المصالح العامة، ومعلوم أن اجتماع النساء والرجال فيما بين الزوال إلى غروب الشمس عند زحمة الحج، فيه الأخطار العظيمة، فإذا رئي ذلك وسمح للمرأة بالتوكيل وللشيخ الكبير ونحوه صار في هذا فرج للجميع وتيسير للجميع. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6984/حكم-تاخير-رمي-الجمرات-الى-اليوم-الثالث-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_164/16405.mp3","categories":["رمي الجمار"]},{"id":8843,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الأخ ناصر حسين هادي اليماني من الوازعية لواء تعز، أخونا يسأل ويقول: حدثونا لو تكرمتم عن رمي الجمرات كيف يكون؟ وحبذا لو فقهتم الناس بالسر من وراء ذلكم التعبد إذا أمكن؟","title":"كيفية رمي الجمار والحكمة من ذلك","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فإن الله جل وعلا -وله الحكمة البالغة والحجة الدامغة- شرع للمسلمين رمي الجمار في الحج تأسيًا بنبيهم عليه الصلاة والسلام؛ لأنه لما حج حجة الوداع رمى الجمار يوم العيد بسبع حصيات رمى جمرة العقبة فقط وهي الجمرة التي تلي مكة بسبع حصيات يكبر مع كل حصاة.\nثم رمى الجمار في الأيام الأخيرة الحادي عشر والثاني عشر والثالث عشر رماها بعد الزوال، كل واحدة رماها بسبع حصيات، يكبر.. مع كل حصاة، ويقول عليه الصلاة والسلام عند أداء الأنساك: خذوا عني مناسككم يعني: يأمر الأمة أن يتعلموا منه، وأن يعملوا بما يشاهدون من عمله عليه الصلاة والسلام وما يسمعون من قوله، فهذا هو الدليل على رمي الجمار.\nوهي تشتمل على سبعين حصاة لمن استكمل الرمي في الأيام الأربعة فرمي يوم العيد سبع حصيات بعد ارتفاع الشمس إلى غروب الشمس كله محل رمي، يكبر مع كل حصاة للجمرة الكبرى التي تلي مكة، وهي جمرة العقبة، وإن رماها في الليل بعد نصف الليل أجزأ ذلك، ولا سيما للضعفاء والعجزة، أما الأقوياء فالسنة لهم أن يكون رميهم مثل ما رماها النبي ﷺ بعد ارتفاع الشمس ضحى، وإن رماها بعد الظهر أو بعد العصر فلا حرج.\nويجوز على الصحيح أن يرميها بعد الغروب أيضًا تلك الليلة لمن لم يرم في النهار إلى آخر الليل.\nوأما الأيام الأخرى الثلاثة وهي أيام التشريق فإنها ترمى بعد الزوال كما رماها النبي عليه الصلاة والسلام، ولا يجوز رميها قبل الزوال؛ لأن ذلك خلاف الشرع المطهر، ويرميها المسلمون بعد الزوال إلى غروب الشمس، ومن لم يتيسر له ذلك من عجز عن ذلك أو شغل عن ذلك جاز رميه لها بعد الغروب تلك الليلة لليوم الذي غربت شمسه في أصح قولي العلماء؛ لأنها حالة حاجة وضرورة، ولا سيما عند كثرة الحجيج، فإن الوقت لا يسع لهم ما بين الزوال إلى غروب الشمس؛ فلهذا جاز على الصحيح أن ترمى بعد غروب الشمس لمن لم يتيسر له الرمي بعد الزوال في ذلك اليوم، يعني: اليوم الذي غابت شمسه، يرميه بعد الغروب.\nوقد ذكر جمع من أهل العلم أن الحكمة في ذلك إهانة الشيطان وإذلاله وإرغامه وإظهار مخالفته؛ لأنه عرض لـإبراهيم عليه الصلاة والسلام حين أراه الله ذبح ابنه إسماعيل، ولكن من المقرر عند أئمة العلم أن الحكمة لابد أن تثبت بدليل واضح من كتاب أو سنة، فإن ثبتت فذلك نور على نور وخير إلى خير، وإلا فالمؤمن يتقبل شرع الله ويعمل به وإن لم يدر الحكمة والعلة في ذلك، مع إيمانه بأن الله سبحانه حكيم عليم، كما قال : إِنَّ رَبَّكَ حَكِيمٌ عَلِيمٌ [الأنعام:83] وقال سبحانه: إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا [النساء:24].\nفهو عليم بما يشرعه لعباده، عليم بما يقدره لهم، عليم بكل حادثة في المستقبل كما أنه عليم لكل بكل ما وقع في الماضي.\nوله الحكمة البالغة في كل شيء سبحانه وتعالى، فإنه له كمال العلم وكمال الحكمة والقدرة، فلا يفعل شيئًا عبثًا أبدًا، فلا يشرع شيئًا عبثًا، ولا يفعل شيئًا عبثًا ، بل كل ذلك لحكمة بالغة وعلة عظيمة وغاية محمودة وإن لم يعلمها البشر، هذا هو الواجب على كل مؤمن أن يعتقد ذلك، فإن الله سبحانه هو الحكيم العليم فيما يقضيه ويقدره، وفيما يشرعه لعباده ، ومن ذلك: مسألة الرمي رمي الجمار. نعم.","link":"https://binbaz.org.sa/fatwas/6998/كيفية-رمي-الجمار-والحكمة-من-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16601.mp3","categories":["رمي الجمار"]},{"id":9105,"question":"وهذه رسالة وصلت إلى البرنامج من المستمع: عباس علي أحمد بخاري من الطائف، يقول فيها: جاء في قول بعض العلماء: السنة أن ترمى الجمار في غير يوم الأضحى، وهناك حديث لـجابر، قوله: رمى النبي ﷺ يوم النحر ضحى ورمى بعد ذلك -بعد الزوال-، فهل معنى ذلك أنه يجوز للحاج أن يؤخر رمي يوم إلى ما بعده أو تأخير الرمي كله إلى آخر أيام التشريق ولا شيء عليه، أفيدونا أفادكم الله؟","title":"بيان القول في وقت رمي الجمار","answer":"الجواب: السنة أن الحاج يرمي يوم العيد، ضحىً سبع حصيات جمرة العقبة، وأما بقية الأيام فبعد الزوال في كل يوم، يرمي الجمرات الثلاث بإحدى وعشرين حصاة، يرمي كل واحدة بسبع بعد الزوال، هذا هو المشروع الذي فعله النبي ﷺ، وهو الذي رواه جابر وغيره عن النبي عليه الصلاة والسلام، روى جابر وغيره رضي الله عن الجميع: أنه رمى يوم العيد بسبع حصيات عليه الصلاة والسلام -جمرة العقبة- ثم حلق رأسه ووزعه على الناس عليه الصلاة والسلام، ثم تطيب وركب إلى البيت فطاف به عليه الصلاة والسلام هذا هو المشروع، ومن أخر الرمي بسبب أعذار له أو زحام ورمى بعد الزوال من يوم الحادي عشر عن جمرة العقبة، أو أخر الجميع إلى اليوم الثالث عشر أو الثاني عشر، ورماها بالترتيب، فرتب الجمار على ما شرع الله فرمى جمرة العيد يوم ...... أولاً بالنية، ثم رمى الجمار الثلاث عن يوم الحادي عشر ثم رماهن عن يوم الثاني عشر مرتباً، أجزأه عند جمع من أهل العلم، ولكن الأولى والأفضل والسنة أن يفعل كما فعله النبي ﷺ فيرمي يوم العيد ضحى وإن رمى في آخر الليل من ليلة العيد أجزأ، ولا سيما الضعفاء والعجزة، وإن رماه يوم العيد الضحى فهو أفضل إذا تيسر ذلك، وبقية الجمار ترمى بعد الزوال، وإن شق بعد الزوال ولم يتيسر له ...... في الظهر والعصر رماه بعد الغروب عن اليوم الماضي، على الصحيح من أقوال العلماء، فله الرمي بالليل عن اليوم الماضي؛ ولكن إذا رمى بعد الزوال وقبل الغروب يكون أفضل وأحوط، وإن شق عليه ذلك ولم يتيسر له الرمي رمى بعد الغروب عن اليوم الذي غربت شمسه هذا هو الصواب وهذا هو المختار، أما قبل الزوال فلا، لا يرمى قبل الزوال في أيام التشريق، لا بعد الفجر ولا قبل الزوال، إنما يرمي بعد الزوال بعد دخول وقت الظهر إلى غروب الشمس هذا هو الأفضل، فإن زحم أو شق عليه رمى بعد الغروب والحمد لله. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7260/بيان-القول-في-وقت-رمي-الجمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22705.mp3","categories":["رمي الجمار"]},{"id":10232,"question":"حجيت مرة ونظرًا لزحمة المرجم في اليوم الثاني من أيام التشريق وزحمة الحرم عند طواف الوداع رجمت في تمام الساعة الحادية عشرة إلا ربع صباحًا، وذلك في يوم التعجيل، هل هذا الرجم صحيح، حيث أنني عندما ذبحت أضحيتي نويتها للجبر عن الخطأ في النسك حيث أنني أحرمت بحجة فقط؟ وإذا كان الرجم غير صحيح ماذا علي؟","title":"حكم من رمى الجمرات قبل الزوال","answer":"الجواب: الرجم قبل الزوال ليس بصحيح في غير يوم العيد، أما يوم العيد فلا بأس، وأما الرجم في أيام التشريق قبل الزوال فإنه لا يجزئ؛ لأنه خلاف الشرع، والرسول ﷺ رمى بعد الزوال وقال: خذوا عني مناسككم وهكذا أصحابه رموا بعد الزوال، والعبادات توقيفية ليست بالرأي، فمن رمى قبل الزوال فرميه غير صحيح وعليه دم عما ترك من الواجب، وإذا كنت ذبحت الذبيحة ناويًا بها عما عليك من الواجب الذي لا تفهمه أجزأت عن هذا الرمي، إذا كنت ناويًا بذلك أنها عما عليك، وليس عليك إلا هذا الرمي، ما حصل منك شيء يوجب الدم إلا هذا، فإن الذبيحة التي نويتها عن النقص الذي عليك تجزئ عن هذا، إلا إن كان عليك أشياء أخرى، فكل شيء يجب فيه ما يجب فيه، إذا كان عليك ترك واجب آخر فإنها لا تجزئ هذه الذبيحة إلا عن واحد فقط، فلو كنت مثلًا تركت المبيت في منى أيام منى أو تركت المبيت في مزدلفة هذان واجبان عليك عنهما عن كل واحد دم. فالحاصل أن الذبيحة التي ذبحتها إنما تجزئ عن واحد مما تركت من الواجبات. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8395/حكم-من-رمى-الجمرات-قبل-الزوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33507.mp3","categories":["رمي الجمار"]},{"id":10604,"question":"هل يصح رمي الجمرات إذا وقع الحصى بجوار الجمرة بحوالي متر، مثل أن يصطدم بعمود الخرسانة المجاور لعدم رؤيته أو لعدم التمييز أو لشدة الزحام؟","title":"عدم إجزاء الرمي إن لم يسقط الحصى في الحوض","answer":"الجواب: لا يجزي إلا إذا سقط في الحوض، أما إذا سقط خارج الحوض فلا يجزي، لكن لو سقط في الحوض وتدحرج لا يضر وخرج، إذا سقط في الحوض كفى، حتى ولو خرج بعد ذلك، المهم أن يقع في الحوض، فلو تدحرج وخرج من الحوض بعد ذلك ما يضر، أما سقوطه في غير الحوض فلا يجزي. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8778/عدم-اجزاء-الرمي-ان-لم-يسقط-الحصى-في-الحوض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32605.mp3","categories":["رمي الجمار"]},{"id":10890,"question":"السائل محمد سعد المطيري يقول: إن والدتي حجت قبل عشرين عامًا، ورمت الجمرات السبع جميعًا، ولم تفرق بينهن، والآن هي كبرت، ولم تستطع الحج وهي متأثرة من حجها الأول، أفيدونا بذلك، جزاكم الله خيرًا.","title":"حكم من رمى الحصيات السبع معاً أثناء رميه الجمرات","answer":"الجواب:  حجها صحيح والحمد لله، وعليها ذبيحة دم تذبح في مكة عن جمعها الجمرات؛ لأن جمعها الجمرات يعتبر جمرة واحدة... كأنها ما رمت إلا حجرًا واحدًا، فعليها دم يذبح في مكة للفقراء عن ترك الجمار التي جمعتها، نعم.","link":"https://binbaz.org.sa/fatwas/9067/حكم-من-رمى-الحصيات-السبع-معا-اثناء-رميه-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28604.mp3","categories":["رمي الجمار"]},{"id":11073,"question":"تقول هذه السائلة: بأنني حججت خمس مرات ولكنني لم أرجم، أوكل زوجي، أو أخي وذلك لشدة الزحام، درءًا للمفاسد، وأنا والحمد لله بأتم الصحة مرتين، أما في الثلاث فأكون حاملًا، أو معي أولادي صغار، فيرجم عني زوجي، فهل حجي صحيح، وهل علي شيء؟","title":"حكم من وكلت محرمها في الرجم عنها لشدة الزحام","answer":"الجواب:  نعم الحج صحيح والحمد لله، وعليك عن السنتين اللتين وكلت فيهما وأنت صحيحة لا مانع بك، عليك فدية دم، ذبيحة عن كل واحدة تذبح في مكة للفقراء، أما السنوات التي فيها أنت حامل تخشين على نفسك، أو عندك الصبية الصغار لا تستطيعين الذهاب بهم، ولا تركهم فلا بأس، وتوكيله صحيح، ولا حرج في ذلك.","link":"https://binbaz.org.sa/fatwas/9251/حكم-من-وكلت-محرمها-في-الرجم-عنها-لشدة-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_288/28821.mp3","categories":["رمي الجمار"]},{"id":11246,"question":"سماحة الشيخ، السائلة: (ع. ع) من المدينة المنورة تقول: لقد من الله علي بأداء الحج في السنة الماضية وقمت بجميع المناسك وأديتها والحمد لله، إلا عند الرمي رمي الجمرات لم أستطع الرمي من شدة الزحام، وناب عني في الرمي ولدي، فهل علي شيء في ذلك؟","title":"حكم التوكيل في الرمي للعاجز","answer":"الجواب: إذا كانت عجزت عن الرمي أو خافت على نفسها من الزحام الشديد فلا بأس، لا عليها شيء إن شاء الله؛ لأنها معذورة. نعم.","link":"https://binbaz.org.sa/fatwas/9427/حكم-التوكيل-في-الرمي-للعاجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29202.mp3","categories":["رمي الجمار"]},{"id":11817,"question":"سمعت من برنامجكم أن الرمي يكفي إذا سقطت الجمرة في الحوض، ولكن عند الرمي لا أعلم هل هي سقطت، أم لا؟ -أي في الحوض- وجهوني جزاكم الله خيرًا.","title":"حكم من شك في وصول حصى الجمار إلى الحوض","answer":"الجواب: الواجب على الحاج أن يتحرى رمي الجمار في الحوض، ولا يقصد الشاخص، يرمي الجمار في الحوض، فإذا غلب على ظنه وقوعها في الحوض، أو علم ذلك؛ كفى، فإن شك في ذلك؛ فعليه أن يعيد الرمي في الوقت، فإذا ذهب الوقت، ذهبت أيام منى، ولم يعد؛ فعليه دم، ذبيحة تذبح في مكة للفقراء عن تركه الرمي، أما ما دام الوقت موجودًا، لم تذهب أيام منى؛ فعليه أن يعيد الرمي حتى يتحقق، أو يغلب على ظنه وقوعها في الحوض. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10001/حكم-من-شك-في-وصول-حصى-الجمار-الى-الحوض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42319.mp3","categories":["رمي الجمار"]},{"id":11818,"question":"عند رمي جمرة العقبة الكبرى أخذت عشر جمرات، قيل لي عند الرمي: احسبي سبع جمرات، ولكن نسيت الحساب وسقط مني واحدة ورميتها كلها، فما الحكم؟ وبماذا توجهونني؟ جزاكم الله خيرًا.","title":"حكم من رمى جمرة العقبة الكبرى بأكثر من سبع حصيات","answer":"الجواب:  إذا كنت رميت الجميع إلا واحدة؛ فقد رميت السبع، والزيادة لا تضر، الثامنة والتاسعة لا تضر، إذا كنت رميت واحدة بعد واحدة؛ وقع الإجزاء، والحمد لله، والزائد لا يضر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10002/حكم-من-رمى-جمرة-العقبة-الكبرى-باكثر-من-سبع-حصيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42320.mp3","categories":["رمي الجمار"]},{"id":12024,"question":"المستمع (أ. س. ف) من مكة المكرمة بعث يسأل ويقول: أثناء رميي للجمرات شكيت في أربع حصيات، هل وصلت إلى مكان الرمي، أو لا؟ فماذا أفعل؟ جزاكم الله خيرًا.","title":"حكم من شك في عدم وصول حصيات إلى مكان الرمي","answer":"الجواب:  إذا كنت أعدت الرمي في وقته؛ فلا بأس، وإلا فعليك دم يذبح بمكة للفقراء عما تركت من الجمار؛ لأن الأربع كثيرة، فالحاصل أن عليك دم يذبح بمكة للفقراء عما تركت من الجمار، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10209/حكم-من-شك-في-عدم-وصول-حصيات-الى-مكان-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43215.mp3","categories":["رمي الجمار"]},{"id":12030,"question":"يقول: في أثناء تأديتي فريضة الحج مرضت مرضًا شديدًا، ارتفاع في درجة الحرارة، مع رعشة شديدة؛ مما تعذر معها قيامي برمي الجمار في اليوم الثاني والثالث، ولكنني وكلت من يقوم بذلك، بالإضافة إلى أنني لم أبت بمنى للسبب ذاته، فهل علي شيء؟ جزاكم الله خيرًا.","title":"حكم من وكَّل غيره برمي الجمار وترك المبيت بمنى لمرضه","answer":"الجواب:  إذا كان الواقع كما ذكرت؛ فليس عليك شيء، الله يقول سبحانه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] والوكيل يقوم مقامك في الرمي، أما عدم المبيت بمنى، فإذا كنت تركت ذلك عجزًا، أو للذهاب إلى الطبيب؛ فلا شيء عليك، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10215/حكم-من-وكل-غيره-برمي-الجمار-وترك-المبيت-بمنى-لمرضه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_432/43221.mp3","categories":["رمي الجمار","المبيت بمنى"]},{"id":12169,"question":"في رمي الجمرات حصل بعض المخالفات، إذ أنني رميت الجمرة الوسطى يوم العيد من الخلف، أي في الخراسانة، دون الجمرة نفسها، وذلك لرؤيتي الحجاج وهم يفعلون ذلك، كما حصل أنني شككت في عدد الحصيات التي رميت بها إحدى الجمرات، إما في يوم العيد، أو في آخر أيام التشريق؟","title":"ما يرمى من الجمرات، وحكم الشك في الرمي","answer":"الجواب:  أما رمي الجمرة الوسطى يوم العيد هذا غير مشروع، وإنما ترمى جمرة العقبة فقط، وهي التي تلي مكة، وهي القصوى من جهة مكة، هذه ترمى يوم العيد بسبع حصيات، أما رمي الوسطى فهذا وجوده كعدمه، ليس عليك فيه شيء؛ لأنها لا ترمى يوم العيد الوسطى، ولا البعيدة التي من جهات منى من جهة مسجد الخيف لا ترمى، إنما يرمى يوم العيد جمرة العقبة فقط، وهي القصوى التي تلي مكة، ترمى يوم العيد بسبع حصيات، فإذا كنت ما رميتها، أو شككت في رميها، ولم ترمها بعد ذلك؛ فعليك دم يذبح بمكة للفقراء، وأما الجمرات الأخرى فهي ترمى يوم الحادي عشر والثاني عشر والثالث عشر، الثلاث كلها ترمى جمرة العقبة والوسطى والبعيدة، لكن يبدأ بالبعيدة التي من جهة مسجد الخيف، يبدأ بها يوم الحادي عشر، ثم الوسطى، ثم جمرة العقبة التي تلي مكة هي الأخيرة، وهكذا في اليوم الثاني عشر وهكذا في الثالث عشر للذي لم يتعجل، يرمى الثلاث كلها، يبدأ بالجمرة التي تلي مسجد الخيف التي في وسط منى، ثم الوسطى، ثم جمرة العقبة التي في آخر منى.. التي من جهة مكة تكون هي الأخيرة، في الأيام الثلاثة الحادي عشر والثاني عشر والثالث عشر، وإذا كنت شككت في رمي واحدة من هذه الثلاث في الحادي عشر، أو في الثاني عشر، إن كنت تعجلت؛ فعليك أن تذبح دمًا، شاة لها سنة إن كانت من المعز، أو ستة أشهر إن كانت من الضأن، يعني: فأكثر، ستة أشهر فأكثر، تذبح بمكة للفقراء، وهذا إذا كان الشك حين الرمي، أما إذا كان الشك طرأ بعد ذلك، وإلا فأنت حين الرمي ما عندك شك، إنما جاء الشك بعد ذلك، فليس عليك شيء، الشك بعد العبادة لا يؤثر، أما إن كان الشك وقت الرمي، شككت ولم تكمل؛ فعليك أن تذبح شاة في مكة، يعني: جذع ضان قد بلغ ستة أشهر فأكثر أو ثني معز فأكثر، ويذبح في مكة للفقراء عن الجمرة التي شككت في رميها، فإن كان الشك حصاة واحدة لم يضر ذلك، تغتفر -إن شاء الله- وإن كنت لم تتعجل، بقيت إلى الثالث عشر، ولم ترم بعض الجمرات في الثالث عشر، أو شككت في رميها حال الرمي، ولم تقم بالواجب، بل تساهلت؛ فعليك -كما تقدم- ذبيحة تذبح في مكة للفقراء، أما إن كان الشك بعد ذلك، بعدما انتهيت من الحج، طرأ عليك شك بعد ذلك، فهذا لا يعول عليه، ولا يعتبر به، بل هو شك لاغي، لا قيمة له، وليس عليك عنه شيء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10355/ما-يرمى-من-الجمرات-وحكم-الشك-في-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44207.mp3","categories":["رمي الجمار"]},{"id":12266,"question":"رسالة مطولة بعث بها أحد الإخوة المستمعين من مكة المكرمة يقول: (خ. م. ن) يقول في رسالته: بسم الله الرحمن الرحيم، أفيدكم بأني من أحد خدمة المطوفين لخدمة الحجاج، وعند طلوعنا إلى عرفات ونزولنا منها إلى منى قرر بعض الحجاج بأن أرمي الجمرات نيابة عن المرضى والطاعنين في السن، الذين لا يقدرون على أداء هذا الواجب، وذلك مقابل أجرة بسيطة أعطوني إياها، ولما أن وصلت إلى رحبة الجمرات لرمي تلك الجمرات، كان الزحام قد بلغ أشده من كثرة الحجاج، فلم أتمكن من هذا العمل الذي أصبح أمانة في عنقي، حيث كادت روحي أن تزهق، وقد أغمي علي، وحملوني إلى المستشفى للعلاج، ولما أن من الله علي بالشفاء؛ عاهدت الله تعالى على ألا أعود لمثل هذا العمل، واستغفرت الله تعالى مئات المرات، وندمت على ذلك كل الندم، والآن هذه الدراهم باقية عندي، فماذا أعمل بها؟ أرجو من سماحتكم توجيهي، وإفادتي ما الذي يجب علي جزاكم الله خيرًا؟","title":"حكم من أخذ أجرة ليرمي عن غيره الجمرات ولم يتمكن","answer":"الجواب:  إذا كنت تعرف أصحاب الدراهم؛ ردها إليهم، وعليهم أن يذبحوا عما تركوا من الرمي ذبيحة، كل واحد يذبح ذبيحة؛ لأن الرمي واجب، وإذا فاتت أيام منى، ولم يرم عليه ذبيحة تذبح في مكة للفقراء بدلًا من هذا الواجب، وترد عليهم دراهمهم، أما إن كنت لا تعلم أهل تلك الدراهم، ولا تعرفهم؛ فالدراهم تشتري بها ذبيحة، وتكملها إن كان .... تستطيع تشتري ذبيحة، وتذبحها بالنية عن صاحبها، الذي لم ترم عنه، والحمد لله، إن كان واحدًا؛ ذبيحة واحدة، وإن كانوا اثنين؛ ذبيحتان، وهكذا بعددهم،  نعم. المقدم: وإن كانت الدراهم لا تكفي للذبيحة؟ الشيخ: الذي يظهر أنه يلزمه؛ لأنه فرط وتساهل، وكان الواجب عليه بعدما عافاه الله أن يرمي إن كانت الأيام موجودة باقية، لم تنته الأيام، ثم هو تساهل في الأمر، ولم يحتط، ولم يقل لهم: أخبروني ... مكانكم وأسماؤكم حتى أرجع إليكم، عنده شيء من التفريط، إذا كان لا يعرفهم، فالمفرط يبرئ ذمته، ويكملها، يكملها ويشتري عن كل واحد ذبيحة، ولو سبع بدنة، أو سبع بقرة، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/10466/حكم-من-اخذ-اجرة-ليرمي-عن-غيره-الجمرات-ولم-يتمكن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_450/45003.mp3","categories":["رمي الجمار"]},{"id":12544,"question":"أحد الإخوة المستمعين، يقول: من جمهورية مصر العربية، محافظة الشرقية، محمد حسن محمد، يقول: حجيت العام الماضي، ورأيت الناس يرمون الجمار بعد الفجر، فرميت معهم، ما حكم ما فعلت؟","title":"حكم رمي الجمار للحاج بعد الفجر","answer":"الجواب:  إذا كان ذلك يوم العيد أجزأ -إن شاء الله- والأفضل بعد الطلوع، بعد طلوع الشمس، لكن ليلة العيد لا بأس بالرمي في آخر الليل في النصف الأخير، ولا بأس بالرمي بعد الفجر، والأفضل بعد طلوع الشمس. أما إذا كان في أيام التشريق: الحادي عشر، والثاني عشر والثالث عشر، فالرمي قبل الزوال لا يجزئ، وعليك أن تعيده بعد الزوال، فإذا كانت الأيام ذهبت، ولم تعد؛ فعليك دم عن ترك الرمي؛ لأنك في حكم من لم يرم، فعليك دم يذبح في مكة للفقراء بسبب ترك الواجب، وهو رمي الجمار بعد الزوال. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10749/حكم-رمي-الجمار-للحاج-بعد-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_456/45612.mp3","categories":["رمي الجمار"]},{"id":12935,"question":"هذا سائل يقول: في رمي الجمار هل يجوز للزوج أن يرمي عن زوجته جميع الجمار؛ وذلك لأنه سيكون معه طفل رضيع، وإن تركه مع أحد، وذهب ليرمي الجمار سيبكي هذا الطفل، وفي حالة عدم وجود طفل هل للزوجة أيضًا أن يرمي عنها الزوج؛ وذلك ليجنبها الزحام الشديد حتى وإن قويت على السير؟","title":"حكم التوكيل في رمي الجمرات","answer":"الجواب:  هذا الموضوع فيه تفصيل، والناس يخطئون فيه كثيرًا، فإذا كانت المرأة قوية تستطيع الرمي؛ وجب عليها الرمي في الليل أو في النهار، فإذا كان زحمة في النهار؛ ترمي بالليل بعد غروب الشمس إلى آخر الليل، كله رمي، ليلة إحدى عشر وليلة اثنا عشر وليلة ثلاثة عشر كله رمي. أما إذا كانت مريضة، أو عجوزًا كبيرة، أو عندها أطفال ليس عندهم من يحفظهم؛ توكل زوجها، أو غيره يرمي عنها والحمد لله، وهكذا الشيخ الكبير والمريض يوكلون، وهكذا الأطفال يرمي عنهم من حج عنهم. أما المرأة القوية التي قد عافاها الله تنظر الوقت المناسب، وترمي فيه، ولا توكل، نعم. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11151/حكم-التوكيل-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50110.mp3","categories":["رمي الجمار"]},{"id":13005,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يقول: أحمد يزيعية من تركيا ويعمل في الرياض، يقول: كتب الله لي العام الماضي الحج، وفي يوم العيد بعد رمي جمرة العقبة ذهبت للطواف بالبيت، وقد تم ذلك وقصرت، ثم لبست ثوبي، وبعد ذلك ذهبت إلى مكان محل تجاري لأصحابي وقمت بالدكان بتنزيل بضاعة من أعلى الدكان، ووقعت، وتورمت قدماي الاثنتان، وعجزت عن رمي الجمرات في اليوم الثاني والثالث، وقد وكلت من يرمي عني في هذين اليومين، فهل حجي صحيح، واكتمل؟ وجهوني جزاكم الله خيرًا.","title":"حكم التوكيل في رمي الجمار للعاجز","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإذا كان الواقع هو ما ذكره السائل؛ فحجك صحيح، والحمد لله، وأنت معذور؛ لأنك بسبب ما أصابك من الحادث لا تستطيع رمي الجمار، فإذا وكلت في ذلك؛ فلا حرج، توكيلك كافٍ، والحمد لله، وهكذا كل مريض، وكل عاجز إذا وكل في رمي الجمار؛ كفى، والحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11222/حكم-التوكيل-في-رمي-الجمار-للعاجز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_471/47101.mp3","categories":["رمي الجمار"]},{"id":14158,"question":"تذكر السائلة في ثاني أسئلتها وتقول: حجيت في سنة من السنوات، وبعد الرمي أخذت معي بعض الجمرات من منى إلى منزلي، هل علي شيء في ذلك؟","title":"حكم أحذ بعض حصى منى إلى البيت","answer":"الجواب: لا، ليس عليك شيء، إذا أخذت شيئًا من الحصى من المرجم أو من الأرض ما فيه شيء لكن لا حاجة إلى هذا الشيء.\nالمقصود إذا رميت الجمار أنت كما شرع الله، كونك تأخذين من حصى الجمار شيء فهذا لا وجه له ولا حاجة إليه، فإن كان المقصود أنه فيه بركة فليس فيه بركة ولا يتبرك به.\nالمقصود ليس عليك شيء، لكن إذا كان المقصود من أخذه أنك تظنين أن فيه بركة هذا غلط، ليس مما يتبرك به بل يحشى من المحل ويلقى في محل آخر. نعم.","link":"https://binbaz.org.sa/fatwas/12599/حكم-احذ-بعض-حصى-منى-الى-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54621.mp3","categories":["رمي الجمار"]},{"id":14238,"question":"المستمع موسى أحمد من المخواة بعث يقول: إنه في العام الماضي أدى فريضة الحج مع عائلته فقام برمي الجمرات وكالة عن زوجته وهي امرأة في منتصف العمر وليس هناك ما يعوقها عن أداء ذلك بنفسها سوى الخوف من الزحام ..الشيخ: أعد.المقدم: يقول: إنه في العام الماضي أدى فريضة الحج مع عائلته، فقام برمي الجمرات وكالة عن زوجته وهي امرأة في منتصف العمر وليس هناك ما يعوقها عن أداء ذلك بنفسها سوى الخوف من الزحام - يقصد مزاحمة الرجال - ولكنه سمع في إحدى حلقات هذا البرنامج أن الذي يوكل وهو قادر على رمي الجمرات يجب عليه ذبح شاة، ويسأل: هل الحج تام أم يجب ذبح شاة؟ وإذا كان يجب الذبح فهل يجوز إرسالها إلى منى لذبحها في العام القادم؟ أم يذبحها في بلدته ويتصدق بها؟ وجزاكم الله خيرًا.","title":"حكم من وكل غيره في رمي الجمار خوفًا من الزحام","answer":"الجواب: إذا كانت ليس بها مانع إلا مجرد خوف الزحام فإنه يفدي عنها بدم شاة تذبح في مكة في الوقت الحاضر، ولا حاجة إلى ذبحها في منى، بل يبعث بها إلى ... يوكل من يذبحها هناك في مكة ويوزع على الفقراء ويكفي ذلك والحمد لله، أما إن كان بها علة؛ لأنها ثقيلة تخشى على نفسها أو مريضة أو ما أشبه ذلك من العلل التي يخشى عليها منها فإنه لا شيء في ذلك والحج صحيح بكل حال، الحج صحيح بكل حال وإنما هل فيه نقص بسبب عدم الرمي أم لا؟ فإذا كان ليس بها مانع شرعي فإن فيه نقص يجبر بالدم الذي يذبح في مكة ويوزع على الفقراء، وهذا جبران للنقص الذي حصل بالتوكيل الذي ليس له مسوغ شرعي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12712/حكم-من-وكل-غيره-في-رمي-الجمار-خوفا-من-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_617/61710.mp3","categories":["رمي الجمار"]},{"id":14261,"question":"أثناء تأديتنا لفريضة الحج قام زوج أختي برمي الجمرات نيابة عنا بحجة أننا نساء ولا نستطيع مواجهة الرجال، هل يجوز هذا؟ وإذا كان لا يجوز وقد وقع بالفعل هل علينا من كفارة؟","title":"ما يلزم من أنابت غيرها في رمي الجمرات؟","answer":"الجواب: إذا كان رميه عنكن بسبب عجزكن لشدة الزحام أو لضعفكن من جهة مرض أو عدم قوة فلا بأس إن شاء الله ولا حرج، أما إن كان تساهلًا وترفهًا فإن عليكن فدية، كل واحدة تذبح ذبيحة في مكة للفقراء عن ترك الرمي، أما إذا كان العلة من زحام شديد خاف عليكن منه، أو كنتن مريضات أو ضعيفات الأجسام لا تستطعن المزاحمة في ذلك والدخول في محل الجمار فنرجو أن يكون الرمي صحيحًا، والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12766/ما-يلزم-من-انابت-غيرها-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62111.mp3","categories":["رمي الجمار","قضايا المرأة"]},{"id":14268,"question":"في حج عام ألف وأربعمائة وثمانية عندما ذهبت لرمي الجمرات رميت ست ووقعت مني واحدة، ولم أتمكن من الحصول عليها لكثرة الزحام هل علينا دم؟ وهل يكون في مكة أم في المكان الذي أقيم فيه؟","title":"ما يجب على من رمى الجمرة بست حصيات؟","answer":"الجواب: يعفى عنك إن شاء الله، ما دامت واحدة يعفى عنها إن شاء الله وليس عليكم شيء، قد ورد عن بعض الصحابة ما يدل على ذلك وأنهم قد يشكون في سقوط الحجر والحجرين فلا يفدون عن ذلك، المقصود أن هذا لا يضرك إن شاء الله، لو أمكنك أنك أخذت حجرًا من تحتك ورميت كان هذا هو الأفضل والأحوط، ولكن مادام الأمر كما قلت فلا شيء عليك، والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12775/ما-يجب-على-من-رمى-الجمرة-بست-حصيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62114.mp3","categories":["رمي الجمار"]},{"id":14804,"question":"المستمع: (خ .م . د) بعث برسالة وضمنها عددًا من الأسئلة، له سؤال طويل جدًا يقول فيه:في عام ألف وأربعمائة وسبعة، أديت فريضة الحج مع زوجتي، وهي كانت حامل، وأديت جميع المناسك الحمد لله بيسرٍ وسهولة، ولكن عند رجم الشيطان في اليوم الثاني، لم أتمكن من رمي الجمرة الثالثة، وكانت زوجتي قد وكلتني برمي جميع الجمرات لها؛ لأنها لم تتمكن من رميها، فإني حائر، وسألت عدة أشخاصٍ عن ذلك، بعضهم يقول لي: حجك صحيح، والبعض يقول لي: يتوجب عليك أن تذبح هدي؛ علمًا بأنني ذبحت هديًا واحدًا فقط لي، وهذا كان أول يوم العيد، قبل أن أرمي الجمرة الثانية؛ لأني قلت: يمكن أنني أنقصت شيئًا من المناسك، وحيث أنني لم أتمكن من رمي الجمرة الثالثة في اليوم الثاني، بعد أن ذبحت في اليوم الأول، هل يجوز لي أن أذبح مرةً أخرى، أم أكتفي بالذبح في المرة الأولى؟وهل أذبح لزوجتي التي وكلتني برمي الجمرات لها؟ وإذا ذبحت لها الآن، هل يجوز ذلك أم وقت الحج؟ أرجو أن تفيدوني عن هذه القضايا. جزاكم الله خيرًا.كما أود إفادتكم بأنني سألت أحد الإخوة وهو إمام جامعٍ في أحد المساجد، وقد أفادني وقال لي: يمكنك أن تتصدق بثمن الهدي بشراء أحد التفاسير الدينية، وتتبرع بها بدلًا من أن تذبح، وفي نفس الوقت قال لي: نقرأ الفاتحة على الرسول ﷺ، وذلك باعتباري وعد مني بإرسال هذه التفاسير، بثمن الهدي، وأنا الآن محتار، وأخاف أن أكون قد أخلفت وعدي، وهل قراءة الفاتحة على الرسول ﷺ بهذه الصورة تعتبر وعدًا كما فعل هذا الشخص؟ وهل يجوز إرسال هذه التفاسير له باعتبارها بدلًا عن الهدي؟كما أفيدكم أيضًا بأنني لم أقم بعمل طواف الوداع، عند انتهائي من الحج، وذلك حسب ما سمعته من الإخوان الذين كانوا معي، قالوا لي: باعتبارك مقيم في المملكة؛ فلا يجب عليك طواف الوداع، سواء أديته أو لم تؤده، هل هذا صحيح، أم حجي ناقص؟ وهل يجوز أن أطوف مرةً ثانية بنية طواف الوداع؟ وهل يجوز لي ذبح هديٍ في هذه الحالة؛ لأني سمعت في إحدى الحلقات في برنامج: نور على الدرب، أحد الإخوة يسأل بأنه إذا لم يطف وسافر كانت الإجابة عليه أن يأتي إلى مكة ويطوف ويذبح هدي، إذا جامع زوجته، في طوال هذه المدة هل ينطبق علي ذلك أم يوجد حكم آخر على هذا الطواف؟وجهوني، جزاكم الله خيرًا.","title":"حكم من ترك رمي الجمرة الثالثة وطواف الوداع","answer":"الجواب: ليس عليك إلا فدية عن ترك الرمي، وعلى الزوجة أيضًا، فعليكما فديتان، عنك ذبيحة، وعنها ذبيحة، إذا كانت الذبيحة التي ذبحتها لم تقصد بها ذبيحة ترك الرمي، وإنما قصدت بها شيئًا آخر، فعليك ذبيحة واحدة عن نفسك، وذبيحة أخرى عن زوجتك، بسبب ترك الرمي، وهذه الذبيحة مثل الضحية، جذع ضأن، أو ثني معز، سليم من العيوب، يذبح في مكة للفقراء، والمساكين، سواء توليته بنفسك، أو وكلت ثقةً في مكة يقوم بذلك. وأما طواف الوداع فهو واجب، والذي قال: ليس عليك وداع وأنت في السعودية، هذا غلط، هذا جهل بحت، بل عليك ذبيحة أيضًا عن ترك الوداع؛ لأنه واجب، على الحاج إذا فرغ من حجه، وأراد السفر؛ أن يطوف للوداع؛ لقول النبي ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت ولقول ابن عباس -رضي الله عنهما-: \"أمر الناس -يعني: أمرهم النبي- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالمرأة الحائض والنفساء ليس عليهما وداع، وأما أنت عليك وداع، فلما تركته، فعليك ذبيحة تذبح في مكة للفقراء، مثل الضحية، جذع ضأن، أو ثني معز. وأما الذي قال لك: تخرج القيمة، فقد غلط، وهذا جهل منه، وهو يدل على عدم بصيرته، وأنه يقول على الله بغير علم، فالثمن لا يجزئ، سواء جعل في كتب للتفسير، أو غيره، إخراج القيمة أو الصدقة بالكتب، كل ذلك لا يقوم مقام الهدي. كذلك قراءة الفاتحة للنبي ﷺ بدعة، لا أساس لها، فنوصيك بالحذر من سؤال من لا يعرف بالعلم، والفضل، والبصيرة في الدين، لا تسأل إلا أهل العلم المعروفين بالورع، والعلم، والبصيرة في دين الله، والسمعة الحسنة؛ لأن كثيراً من الناس يقول على الله بغير علم، ويفتي على غير بصيرة، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13305/حكم-من-ترك-رمي-الجمرة-الثالثة-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64206.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":14812,"question":"المستمع: (خ .م . د) بعث برسالة وضمنها عددًا من الأسئلة، له سؤال طويل جدًا يقول فيه:في عام ألف وأربعمائة وسبعة، أديت فريضة الحج مع زوجتي، وهي كانت حامل، وأديت جميع المناسك الحمد لله بيسرٍ وسهولة، ولكن عند رجم الشيطان في اليوم الثاني، لم أتمكن من رمي الجمرة الثالثة، وكانت زوجتي قد وكلتني برمي جميع الجمرات لها؛ لأنها لم تتمكن من رميها، فإني حائر، وسألت عدة أشخاصٍ عن ذلك، بعضهم يقول لي: حجك صحيح، والبعض يقول لي: يتوجب عليك أن تذبح هدي؛ علمًا بأنني ذبحت هديًا واحدًا فقط لي، وهذا كان أول يوم العيد، قبل أن أرمي الجمرة الثانية؛ لأني قلت: يمكن أنني أنقصت شيئًا من المناسك، وحيث أنني لم أتمكن من رمي الجمرة الثالثة في اليوم الثاني، بعد أن ذبحت في اليوم الأول، هل يجوز لي أن أذبح مرةً أخرى، أم أكتفي بالذبح في المرة الأولى؟وهل أذبح لزوجتي التي وكلتني برمي الجمرات لها؟ وإذا ذبحت لها الآن، هل يجوز ذلك أم وقت الحج؟ أرجو أن تفيدوني عن هذه القضايا. جزاكم الله خيرًا.كما أود إفادتكم بأنني سألت أحد الإخوة وهو إمام جامعٍ في أحد المساجد، وقد أفادني وقال لي: يمكنك أن تتصدق بثمن الهدي بشراء أحد التفاسير الدينية، وتتبرع بها بدلًا من أن تذبح، وفي نفس الوقت قال لي: نقرأ الفاتحة على الرسول ﷺ، وذلك باعتباري وعد مني بإرسال هذه التفاسير، بثمن الهدي، وأنا الآن محتار، وأخاف أن أكون قد أخلفت وعدي، وهل قراءة الفاتحة على الرسول ﷺ بهذه الصورة تعتبر وعدًا كما فعل هذا الشخص؟ وهل يجوز إرسال هذه التفاسير له باعتبارها بدلًا عن الهدي؟كما أفيدكم أيضًا بأنني لم أقم بعمل طواف الوداع، عند انتهائي من الحج، وذلك حسب ما سمعته من الإخوان الذين كانوا معي، قالوا لي: باعتبارك مقيم في المملكة؛ فلا يجب عليك طواف الوداع، سواء أديته أو لم تؤده، هل هذا صحيح، أم حجي ناقص؟ وهل يجوز أن أطوف مرةً ثانية بنية طواف الوداع؟ وهل يجوز لي ذبح هديٍ في هذه الحالة؛ لأني سمعت في إحدى الحلقات في برنامج: نور على الدرب، أحد الإخوة يسأل بأنه إذا لم يطف وسافر كانت الإجابة عليه أن يأتي إلى مكة ويطوف ويذبح هدي، إذا جامع زوجته، في طوال هذه المدة هل ينطبق علي ذلك أم يوجد حكم آخر على هذا الطواف؟وجهوني، جزاكم الله خيرًا.","title":"حكم من ترك رمي الجمرة الثالثة وطواف الوداع","answer":"الجواب: ليس عليك إلا فدية عن ترك الرمي، وعلى الزوجة أيضًا، فعليكما فديتان، عنك ذبيحة، وعنها ذبيحة، إذا كانت الذبيحة التي ذبحتها لم تقصد بها ذبيحة ترك الرمي، وإنما قصدت بها شيئًا آخر، فعليك ذبيحة واحدة عن نفسك، وذبيحة أخرى عن زوجتك، بسبب ترك الرمي، وهذه الذبيحة مثل الضحية، جذع ضأن، أو ثني معز، سليم من العيوب، يذبح في مكة للفقراء، والمساكين، سواء توليته بنفسك، أو وكلت ثقةً في مكة يقوم بذلك. وأما طواف الوداع فهو واجب، والذي قال: ليس عليك وداع وأنت في السعودية، هذا غلط، هذا جهل بحت، بل عليك ذبيحة أيضًا عن ترك الوداع؛ لأنه واجب، على الحاج إذا فرغ من حجه، وأراد السفر؛ أن يطوف للوداع؛ لقول النبي ﷺ: لا ينفر أحد منكم حتى يكون آخر عهده بالبيت ولقول ابن عباس -رضي الله عنهما-: \"أمر الناس -يعني: أمرهم النبي- أن يكون آخر عهدهم بالبيت، إلا أنه خفف عن المرأة الحائض\" فالمرأة الحائض والنفساء ليس عليهما وداع، وأما أنت عليك وداع، فلما تركته، فعليك ذبيحة تذبح في مكة للفقراء، مثل الضحية، جذع ضأن، أو ثني معز. وأما الذي قال لك: تخرج القيمة، فقد غلط، وهذا جهل منه، وهو يدل على عدم بصيرته، وأنه يقول على الله بغير علم، فالثمن لا يجزئ، سواء جعل في كتب للتفسير، أو غيره، إخراج القيمة أو الصدقة بالكتب، كل ذلك لا يقوم مقام الهدي. كذلك قراءة الفاتحة للنبي ﷺ بدعة، لا أساس لها، فنوصيك بالحذر من سؤال من لا يعرف بالعلم، والفضل، والبصيرة في الدين، لا تسأل إلا أهل العلم المعروفين بالورع، والعلم، والبصيرة في دين الله، والسمعة الحسنة؛ لأن كثيراً من الناس يقول على الله بغير علم، ويفتي على غير بصيرة، نسأل الله العافية والسلامة، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13305/حكم-من-ترك-رمي-الجمرة-الثالثة-وطواف-الوداع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_642/nour_64206.mp3","categories":["الطواف بالبيت","السعي","رمي الجمار"]},{"id":14918,"question":"هذه رسالة وردتنا من خميس مشيط من المرسل (ع. ج. ع) يقول فيها: هو أنني حجيت في عام تسع وتسعين وثلاثمائة وألف هجرية أول حجة، ولا زالت أول حجة حتى الوقت الحاضر، وحدث عندي في الحج أنني قضيت جميع المناسك، ولكن حدث أنني رميت يوم العيد الجمرة الكبرى، وفي اليوم الثاني رميت جمرة واحدة فقط، وهو عن طريق النسيان، مع عدم المعرفة الكاملة، وفي اليوم الثالث رحت مع جماعة ورميت الجمرات الثلاث، ولكن نسيت أني رميت جمرة واحدة اليوم الثاني، وما ذكرتها إلا بعد حين، يقول: يعني بعد سنة أو سنتين ونصف تذكرت التي ما رميت، ويريد إفتائه ما الذي عليه؟ وما يجب عليه في هذا المقام؟وفقكم الله.","title":"ما يلزم من نسي رمي إحدى الجمرات؟","answer":"الجواب: عليه أن يهدي هديًا يذبح في مكة، عليه ذبيحة عن ترك الرمي الذي تركه في الحادي عشر، يذبحها في مكة، يعني يوكل ثقة، أو هو بنفسه يأتي يذبحه في مكة؛ إما ثني معز، أو جدع ضان، مثل هدي التمتع والقران، سواء مثل الضحية يذبحها في مكة ويقسمها بين الفقراء عما ترك من الرمي، نعم، وهذا يجبر عنه، يجبر الحج. السؤال: لكن لو حج ورماها مع الـ ...\nالجواب: لا ما تجزئ؛ فات وقتها، فات وقتها، نعم.","link":"https://binbaz.org.sa/fatwas/13417/ما-يلزم-من-نسي-رمي-احدى-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_646/nour_64603.mp3","categories":["رمي الجمار"]},{"id":14949,"question":"أيضًا يقول: من لم يتمكن من المبيت بمنى في أول ليلة من ليالي أيام التشريق، هل يرمي الجمرات في أول أيام التشريق؟ وكذلك من لم يتمكن من المبيت في الليلتين الأوليين هل يمكنه رمي الجمرات عن اليومين في اليوم الثاني من أيام التشريق؟","title":"هل يرمي الجمرات من لم يبيت بمنى؟","answer":"الجواب: رمي الجمرات نسك مستقل، والمبيت نسك مستقل، والواجب على الحاج هذا وهذا، على الحاج أن يبيت في منى في الليلة الحادية عشرة، والثانية عشرة إن تعجل، فإن لم يتعجل بات الثالثة عشرة أيضًا، وعليه أن يرمي الجمار في الأيام كلها، يوم العيد والحادي عشر والثاني عشر إن تعجل، وعليه أن يرميها في الرابع والثالث عشر إن لم يتعجل، فإذا ترك المبيت لعذر كالسقاة والرعاة والمريض الذي احتاج إلى المستشفى والنقلة إليه، أو نحوه ممن له شغل شاغل يشغله عن المبيت، وهو شغل مهم فلا حرج عليه، وكذلك الرمي مستقل، إن تيسر أن يرمي يوم العيد وفي الأيام الثلاثة كل شيء في وقته، فهو سنة وهو الأفضل، ويرمي جمرة العقبة يوم العيد نهارًا هذا هو الأفضل، وإن رماها في آخر الليل كالضعفة أجزأت على الصحيح. وهكذا في اليوم الحادي عشر يرميها بعد الزوال نهارًا، وإن شق عليه ذلك رماها ليلًا في الليلة الثانية عشرة لليوم الحادي عشر على الصحيح، والمسألة خلافية في الليل، لكن هذا هو الأرجح، يجوز رميها بعد غروب الشمس إلى آخر الليل تبعًا لليوم الذي قبلها، وهكذا في اليوم الثاني عشر له أن يرمي في النهار، وهو السنة بعد الزوال، فإن شق عليه ذلك رمى بعد الغروب لليلة الثالثة عشرة، وأجزأه ذلك على الصحيح، وعليه أن يبيت ويوم من يوم الثالث عشر؛ لكونه أدركه المساء ولم يتعجل. ولا يجوز الرمي أبدًا قبل الزوال في الأيام الثلاثة؛ لأن الرسول رمى -عليه الصلاة والسلام- رمى بعد الزوال في الحادي عشر والثاني عشر والثالث عشر، وقال: خذوا عني مناسككم وما يروى عن بعض السلف من الترخص والرمي قبل الزوال، وما أفتى به بعض المتأخرين كله غلط، ولا يجوز الأخذ به، بل يجب التقيد بما فعله الرسول ﷺ وأصحابه وهو الرمي بعد الزوال، لكنه -عليه الصلاة والسلام- لم يحدد النهاية، ولم يقل لا ترموا بعد غروب الشمس، فمن هذا جاز الرمي بعد غروب الشمس توسعة للمسلمين؛ لأن العدد كثير والوقت الذي بين الزوال والغروب ضيق؛ فلهذا ترجح قول من قال بجواز الرمي بعد الغروب إلى آخر الليل تابعًا لليوم الذي قبل الليلة، نعم. السؤال: أيضًا يقول: من أحرم بعمرة من ميقاته ثم تحلل.\nالشيخ: من تمام السؤال الأول ولو أخر الرمي أخر رمي الحادي عشر إلى الثاني عشر، ثم رتبهما بالنية بعد الزوال، أو أخر الثاني عشر إلى الثالث عشر ورتبهما بالنية فرمى اليوم الأول كاملًا بنيته، ثم رمى اليوم الذي بعده كاملًا بنيته، فلا حرج عند جمع من أهل العلم، ولكن رمي كل شيء في وقته هو الأولى والأفضل، والعاجز الذي لا يستطيع الرمي يوكل كما يرمى عن الصبيان لعجزهم، فهكذا يرمى عن العجائز والشيوخ الكبار والمرضى وأشباههم ممن يخشى عليهم من الرمي، لما يقع فيه من المزاحمة والمضايقة، نعم.","link":"https://binbaz.org.sa/fatwas/13449/هل-يرمي-الجمرات-من-لم-يبيت-بمنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_649/nour_64903.mp3","categories":["رمي الجمار"]},{"id":15021,"question":"نبدأ برسالة المستمع صالح زيد العتيبي، من مكة المكرمة، يقول فيها: ما حكم من ترك الرمي للأيام الثلاثة بدون عذر أو بعذر؟","title":"حكم من ترك الرمي","answer":"الجواب:  بسم الله الرحمن الرحيم.  الحمد لله رب العالمين، والصلاة والسلام على عبده ورسوله، وأمينه على وحيه، وصفوته من خلقه، نبينا وإمامنا وسيدنا محمد بن عبدالله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: أما من تركها بغير عذر، هذا عاص لربه، وهو على خطر من عاقبة هذه المعصية، وعليه التوبة إلى الله ، والإنابة إليه، صادقًا بالندم على ما مضى منه، والعزيمة أن لا يعود في ذلك. وعليه دم أيضًا، مع التوبة دم يذبحه في مكة للفقراء؛ لأن الرمي واجب، وقد تركه، فعليه أن ينحر عن هذا دمًا، يوزع بين الفقراء في مكة، والدم المراد منه إذا أطلق: رأس من الغنم؛ ثني معز، أو جذع ضأن، أو سبع بدنة، أو سبع بقرة، هذا هو المراد بالدم. أما المعذور؛ فهذا لا إثم عليه، وعليه أن يوكل، كالمريض ونحوه، لا حرج عليه في التأخر، ولكن يلزمه أن يوكل من يرمي عنه، نعم.","link":"https://binbaz.org.sa/fatwas/13522/حكم-من-ترك-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65301.mp3","categories":["رمي الجمار"]},{"id":15117,"question":"نعود مع مطلع هذه الحلقة إلى رسالة المستمع محمد صالح الشرقي المري، من مدينة المرة بدولة قطر، الأخ محمد عرضنا له سؤال في حلقة مضت، وفي هذه الحلقة يقول: في آخر يوم من أيام التشريق حيث حجيت ذلكم العام، عند رمي الجمرات وزعت الحصيات على جيوبي، وجعلت سبع الحصيات في الجيب الأيمن، وسبعًا في الأيسر، وسبعًا في جيب الصدر، ورميت الجمرات الصغرى والوسطى والكبرى، وعندما ذهبت إلى المنزل، لقيت حصاة واحدة في جيب الصدر، فهل علي أي شيء؟جزاكم الله خيرًا.","title":"حكم من رمى الجمار بست حصيات","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالصواب في هذه المسألة أنه لا شيء عليك، وأن الحصاة الواحدة تغتفر، والحمد لله، قد ثبت عن بعض الصحابة أنهم لما رجعوا من حجهم، قال بعضهم: \"رميت بست\" وقال الآخر: \"رميت بسبع\" فلم يعب بعضهم على بعض، فالواحدة لا حرج فيها -إن شاء الله-، ولا ينبغي تعمد ذلك. لكن من نسيها أو غلط فلا حرج عليه، أما التعمد فلا يجوز التعمد، يجب أن ترمى كل واحدة بسبع، كما رماها النبي ﷺ، وقال بعض العلماء: إن عليه مد من حنطة، أو نصف صاع من الحنطة، أو الرز بدل الحصاة الواحدة، ولكن ليس عليه دليل، فالأمر في هذا -إن شاء الله- واسع، وأنت معفو عنك -إن شاء الله-، نعم. المقدم: إن شاء الله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13617/حكم-من-رمى-الجمار-بست-حصيات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_495/49501.mp3","categories":["رمي الجمار"]},{"id":15700,"question":"السائل حامد العمري من مكة المكرمة، له مجموعة من الأسئلة، يقول سماحة الشيخ: ما حكم الخروج من المزدلفة بعد الساعة الواحدة والنصف ليلًا لرمي جمرة العقبة؛ خوفًا من الزحام الشديد؟","title":"حكم رمي جمرة العقبة بعد منتصف الليل","answer":"الجواب: النبي ﷺ رخص للضعفة من النساء، وكبار السن والأطفال، وأتباعهم أن يخرجوا من مزدلفة بليل، يعني: آخر الليل، النصف الأخير، بعد أن يغيب القمر، فلا حرج، إذا خرج الضعفاء من النساء، وأتباعهم، وكبار السن ونحوهم، وتوجهوا إلى منى حتى يرموا الجمرة قبل الزحمة؛ فلا بأس بذلك، كما رخص النبي لهم -عليه الصلاة والسلام-.\nأما الأقوياء فالأفضل لهم المبيت في مزدلفة، والوقوف بها بعد صلاة الفجر، مستقبل القبلة، يدعون الله، ويسألونه، ويضرعون إليه، ويرفعون أيديهم بالدعاء، كما فعل النبي ﷺ، فإنه صلى الفجر في مزدلفة، ثم وقف بها حتى أسفر، ورفع يديه، ودعا ربه؛ حتى أسفر جدًا، مستقبل القبلة، فلما أسفر جدًا، انصرف إلى منى، قبل طلوع الشمس، هذا السنة، للحجاج أن يصلوا في مزدلفة الفجر، وأن يقفوا بالمشعر الحرام بمزدلفة، كل مزدلفة موقف -كلها- يستقبلون القبلة، ويرفعون أيديهم، ويدعون بما يسر الله من الدعاء، بقبول حجهم، وبحصول المغفرة، والنجاة من النار، إلى غير هذه من الدعوات الطيبة، فإذا أسفروا انصرفوا قبل طلوع الشمس، ينصرفون إلى منى قبل أن تطلع الشمس، بعد الإسفار، قال عمر : «كانوا في الجاهلية لا ينصرفون حتى تطلع الشمس، ويقولون: أشرق ثبير، والنبي خالفهم، فأفاض من مزدلفة قبل أن تطلع الشمس» -عليه الصلاة والسلام-، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/14258/حكم-رمي-جمرة-العقبة-بعد-منتصف-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57309.mp3","categories":["رمي الجمار"]},{"id":15796,"question":"بعد هذا ننتقل إلى سؤال آخر لأخينا صاحب هذه الرسالة؛ إذ يقول: حججت في العام الماضي، ولله الحمد والمنة، وقد رميت الجمرات عن زوجتي، ولم تكن حاملًا ولا مريضة، وكان معي أربعة أطفال صغار، وشاهدت الزحام فلم أرها تستطع الرمي، فهل هذا يجوز أم أنها تركت واجبًا؟ وماذا عليها الآن؟","title":"حكم التوكيل في رمي الجمرات","answer":"الجواب: إذا كان الحال ما ذكرتم فلا شيء عليها؛ لأن تعاطيها الرجم -رمي الحجارة- مع الأطفال خطر عظيم، ولرعاة الأطفال خطر عظيم، فهي معذورة بوجود الأطفال لديها بالتوكيل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14386/حكم-التوكيل-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74302.mp3","categories":["قضايا المرأة","رمي الجمار","النيابة في الحج"]},{"id":15906,"question":"تقول: حجت فتاة في سنة من السنوات، وبعد ذلك وعند رمي الجمرات كانت تعتقد أنه لا بد من رمي الجمرات في نفس الحجر الواقف، وليس في الحوض أو الصحن، ولوجود الزحمة لا ترى الجمرة فكانت ترمي حجرًا زائدًا في جميع المواقع الثلاث، فيكون حاصل الجمرات ثمان جمرات في كل موقع، هل رميها الحجر الزائد الذي يعد في ترتيبه الثامن يترتب عليه شيء، أم أن ما فعلته صحيح؟جزاكم الله خيرًا.","title":"حكم الزيادة في رمي الجمرات على سبع","answer":"الجواب: إذا كان رميها الأحجار قد وقع في الحوض كفى، سواء أصاب الشاخص، أو ما أصاب الشاخص.  أما الحجر الزائد فلا يضرها، لكن ليس لها تعمده إلا من حاجة، كأن تشك هل رمت سبعًا أم أقل فلا بأس أن ترمي ثامن تاسع حتى تتيقن أنها رمت السبع، أما مع العلم بأنها رمت سبعًا فلا حاجة إلى الزيادة، ولا وجه له، ولكن من الواجب رمي الشاخص.  المقصود: رمي الحوض فإذا كانت تعلم، قد غلب على ظنها أن الحجر وقع في الحوض كفى، والحمد لله، نعم.\nالمقدم: جزاكم الله خيرًا. هل يترتب عليها كفارة أو شيء إذا ما رمت بثمان؟ الجواب: إذا كانت رمت سبعًا كفى، والثامن لا حاجة إليه، فإذا كان يغلب على ظنها أن السابعة وصلت الحوض كفى، والحمد لله، وليس عليها شيء، أما إذا كانت شاكة ما تدري فعليها دم، يذبح في مكة للفقراء؛ لأن الشاك لم يؤد الواجب، نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/14501/حكم-الزيادة-في-رمي-الجمرات-على-سبع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74606.mp3","categories":["رمي الجمار"]},{"id":16019,"question":"يقول: في أحد الأعوام حجيت -ولله الحمد- وعندما أتينا من مزدلفة إلى منى لرمي الجمرات ذهبت ورميت سبع جمرات، وعندما سألت في المساء قالوا لي: ليس بسبع، إنما إحدى وعشرون جمرة، ثم قمت في اليوم الثالث، فرميت الجمرات المتبقية علي، هل علي شيء؟ أرجو الإفادة.","title":"حكم ترك رمي الجمرات أو بعضها","answer":"الجواب: أما يوم العيد فليس فيه إلا سبع؛ جمرة العقبة ترمى بسبع حصيات، أما الأيام الأخرى؛ الحادي عشر، والثاني عشر فإن الواجب رمي الثلاث الجمار، كل واحدة بسبع، الأولى والوسطى والأخيرة، كل واحدة بسبع، والأخيرة هي التي تلي مكة، وتكون هي التالية التي رماها الناس يوم العيد، تكون هي الأخيرة، وترمى الجمرتان الأوليان قبلها الأولى التي تلي مسجد الخيف في داخل منى، ثم الوسطى، ثم جمرة العقبة التي رماها الناس يوم العيد، وهكذا يوم الثاني عشر ترمى الثلاث، كل واحدة بسبع حصيات. فإذا كنت رميت الثلاث يوم الحادي عشر، والثاني عشر كل واحدة بسبع، فليس عليك شيء، وإن كنت تركت هذه الجمرات، أو بعضها؛ فعليك دم، يذبح في مكة للفقراء إذا كنت تركت سبعًا من الحادي عشر، أو تركتها كلها، أو تركت ثنتين منها، يعني أربعة عشر، فإن عليك دم يذبح في مكة للفقراء، أما إذا كنت كملت إحدى وعشرين، يوم الحادي عشر، وإحدى وعشرين يوم الثاني عشر، ثم نفرت قبل الغروب؛فليس عليك شيء. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14654/حكم-ترك-رمي-الجمرات-او-بعضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74720.mp3","categories":["رمي الجمار"]},{"id":16029,"question":"يقول: في أحد الأعوام حجيت -ولله الحمد- وعندما أتينا من مزدلفة إلى منى لرمي الجمرات ذهبت ورميت سبع جمرات، وعندما سألت في المساء قالوا لي: ليس بسبع، إنما إحدى وعشرون جمرة، ثم قمت في اليوم الثالث، فرميت الجمرات المتبقية علي، هل علي شيء؟ أرجو الإفادة.","title":"حكم ترك رمي الجمرات أو بعضها","answer":"الجواب: أما يوم العيد فليس فيه إلا سبع؛ جمرة العقبة ترمى بسبع حصيات، أما الأيام الأخرى؛ الحادي عشر، والثاني عشر فإن الواجب رمي الثلاث الجمار، كل واحدة بسبع، الأولى والوسطى والأخيرة، كل واحدة بسبع، والأخيرة هي التي تلي مكة، وتكون هي التالية التي رماها الناس يوم العيد، تكون هي الأخيرة، وترمى الجمرتان الأوليان قبلها الأولى التي تلي مسجد الخيف في داخل منى، ثم الوسطى، ثم جمرة العقبة التي رماها الناس يوم العيد، وهكذا يوم الثاني عشر ترمى الثلاث، كل واحدة بسبع حصيات. فإذا كنت رميت الثلاث يوم الحادي عشر، والثاني عشر كل واحدة بسبع، فليس عليك شيء، وإن كنت تركت هذه الجمرات، أو بعضها؛ فعليك دم، يذبح في مكة للفقراء إذا كنت تركت سبعًا من الحادي عشر، أو تركتها كلها، أو تركت ثنتين منها، يعني أربعة عشر، فإن عليك دم يذبح في مكة للفقراء، أما إذا كنت كملت إحدى وعشرين، يوم الحادي عشر، وإحدى وعشرين يوم الثاني عشر، ثم نفرت قبل الغروب؛فليس عليك شيء. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14654/حكم-ترك-رمي-الجمرات-او-بعضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_747/nour_74720.mp3","categories":["رمي الجمار"]},{"id":16068,"question":"رسالة وصلت إلى البرنامج باسم أحد الإخوة المستمعين يقول في نهاية رسالته: مهندس محمد عبدالواحد، له سؤال طويل يتعلق برمي الجمرات، ملخص هذا  أنه أخطأ في رمي الجمرات بين الجمرة الكبرى والوسطى والصغرى، ويقول: لم يكتشف حاله إلا فيما بعد، فماذا عليه الآن؟ جزاكم الله خيرًا.","title":"حكم الترتيب في رمي الجمرات","answer":"الجواب: إن كان رماهن، لكنه أخطأ في الترتيب، فنرجو أن يعفو الله عنه من أجل الجهل، والرجم قد حصل، والرمي قد حصل، فإذا كان رمى في الأولى، ثم الأخيرة، ثم الوسطى، أو رمى الوسطى، ثم الأولى، ثم الأخيرة، ونحو ذلك، فالصحيح أنه يجزئه -إن شاء الله- إذا كان فات الوقت. أما إن كان الوقت باقيًا؛ فإنه يعيد ما بعد الأولى، يعيد ما رماه قبل الأولى، يعيده، فإذا كان رمى الوسطى، ثم الأولى يعيد الوسطى، ثم الأخيرة حتى يحصل الترتيب. وإذا كان رمى الأخيرة ثم الوسطى، ثم الأولى، يعيد الوسطى، والأخيرة حتى تكون الأولى في محلها، لكن لو لم ينتبه إلا بعد ذهاب الوقت؛ أجزأه -إن شاء الله- ولا دم عليه، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14704/حكم-الترتيب-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74903.mp3","categories":["رمي الجمار"]},{"id":16069,"question":"يسأل أيضًا حول نفس الموضوع تقريبًا يقول: ما حكم الحصيات التي لم تنزل من الحوض، أو لم تضرب في العمود؟ وجهوني جزاكم الله خيرًا.","title":"ما حكم وصول حصيات الرمي إلى الحوض؟","answer":"الجواب: المطلوب وصول الحجر إلى الحوض، فإذا وصل إلى الحوض كفى، ولو لم يرم الشاخص -الجدار- ولو نزلت بعد ذلك إلى الأرض، متى وصلت الحوض كفى، وإذا تدحرجت، ونزلت؛ فلا يضره، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14705/ما-حكم-وصول-حصيات-الرمي-الى-الحوض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_749/nour_74904.mp3","categories":["رمي الجمار"]},{"id":16198,"question":"تقول صاحبة الرسالة: رميت الجمرات في اليوم الأول، وفي اليوم الثاني وكلت زوجي، رغم أني قادرة؛ وذلك لأسباب وهو أننا كنا في مكان بعيد، والرجل يخشى علينا من التعب، فقمت أنا ومجموعة من النساء بتوكيل أزواجنا، هل ما فعلناه صحيح، جزاكم الله خيرًا.","title":"حكم التوكيل في رمي الجمرات مع القدرة","answer":"الجواب: فيه نظر، مع القدرة فيه نظر، والواجب على الحاج أن يرمي الجمرات بنفسه، وهكذا الحاجة المرأة ترمي بنفسها، إلا عند العجز لمرضها، أو كونها حبلى، أو عندها رضيع لا تستطيع تركه؛ فهي معذورة أو كبيرة السن، أما مجرد التعب فتلافيه يمكن بالسيارة .. ركوب السيارات، يمكن ركوب السيارة، والتقرب إلى المرجم بالسيارات. فالأحوط لكن الفدية.. ذبيحة عن كل واحدة منكن بسبب ترك الرمي؛ لأن الوكالة بدون وجه شرعي حكمها حكم الترك، فعلى كل واحدة منكن ذبيحة تذبح بمكة للفقراء؛ بسبب عدم الرمي الذي تركتنه بدون عذر شرعي؛ لأن مجرد البعد ليس بعذر، لوجود السيارات، نعم. المقدم: جزاكم الله خيرًا، سماحة الشيخ يتعذر للسيارات الحركة في مثل هذا الموسم ما بين الجمرات، والأماكن التي يقيم فيها الناس، فما هو توجيهكم؟ الجواب: مثلما أن السيارة تشيل الرجال تشيل النساء، تقربهم، إلا إذا كان ما هناك سيارة توصل، وهي عاجزة فهي معذورة كالمريضة، إذا كان ما هناك سيارة تنقل النساء، والرجل يمشي بنفسه، ويبات إلى الصبح؛ فهذا معذور، كالرجل العاجز إذا عجز؛ يوكل. المقدم: جزاكم الله خيرًا، الواقع أنه يتعذر حركة السيارات؟ الشيخ: هذه قاعدة، قاعدة: لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286] فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] فإذا كان الرجل كبيرًا في السن، أو عنده بعض المرض لا يستطيع المشي، وليس هناك سيارة توصله، أو المرأة كذلك؛ فالحكم واحد ليس عليهم شيء، والوكالة تجزئ. المقدم: بارك الله فيكم، وجزاكم الله خيرًا، بالنسبة للزحام الشديد هل تعذر المرأة في ترك الرمي من أجل شدة الزحام سماحة الشيخ؟ الشيخ: نعم، إذا كان عليها خطر؛ فهو عذر لها، بالتوكيل، نعم. المقدم: توكل؟ الشيخ: نعم، وإن رمت بالليل متيسرة بالليل عن يوم العيد، وعن يوم الحادي عشر، والثاني عشر؛ كفى في الليل، إذا تيسر لها من دون مشقة، وخطر، نعم. المقدم: لعله أيسر.  الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14872/حكم-التوكيل-في-رمي-الجمرات-مع-القدرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75103.mp3","categories":["رمي الجمار","قضايا المرأة"]},{"id":16532,"question":"سماحة الشيخ! تقول السائلة أم أحمد: هل يجوز للزوجة أن توكل زوجها لرمي جمرة العقبة؟ وهل عليها هدي في ذلك، نظرًا للزحام، ومعها أطفال في ذلك الوقت؟","title":"هل يجوز للمرأة أن توكل زوجها لرمي الجمار؟","answer":"الجواب: نعم، إذا كانت عاجزة لها أن توكل زوجها، أو غيره، توكل ثقة يرمي عنها إذا كانت ضعيفة لا تستطيع الزحام، أو كبيرة السن لا تسطيع، أو عندها أطفال ما تستطيع تتركهم، توكل زوجها إذا كان ثقة، أو غيره من الثقات يرمي عنها، ولا حرج.","link":"https://binbaz.org.sa/fatwas/15253/هل-يجوز-للمراة-ان-توكل-زوجها-لرمي-الجمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58308.mp3","categories":["رمي الجمار","النيابة في الحج"]},{"id":16533,"question":"تقول أخيرًا: هل على المتعجل في رمي الجمرات هدي إذا سافر يوم الحادي عشر من مكة؟","title":"حكم تعجل الحاج وسفره في يوم الحادي عشر","answer":"الجواب: لا يجوز لأحد أن يسافر قبل الرمي يوم الثاني عشر، التعجل يكون في الثاني عشر، فليس لأحد أن يتعجل قبل الثاني عشر، فإذا رمى الجمرة يوم الثاني عشر؛ له أن يتعجل، يطوف للوداع، ثم يسافر، أما أن يتعجل في يوم الحادي عشر لا، أو في صباح الثاني عشر لا، التعجل يكون في اليوم الثاني عشر بعد الرمي، بعد الزوال، ثم إذا رمى بعد الزوال يذهب إلى مكة، ويطوف طواف الوداع إذا كان طاف طواف الإفاضة؛ يطوف طواف الوداع، ثم يسافر إذا أحب، وإن كان ما طاف طواف الإفاضة؛ يطوف طواف الإفاضة، طواف الحج ويسافر، يكفيه عن طواف الوداع، إذا كان بعد الرمي في اليوم الثاني عشر، أو اليوم الثالث عشر، وإذا طاف طوافين، طواف الحج، وطواف الوداع؛ كان أكمل، وأفضل. المقدم: أحسن الله إليكم، سماحة الشيخ الذي سافر يوم الحادي عشر ماذا يلزمه؟ الجواب: يلزمه دمان: دم عن ترك الرمي، ودم عن ترك الوداع؛ لأن الوداع ما هو في محله، طاف في غير محل الوداع، ودم ثالث إذا كان ما بات ليلتي إحدى عشر، واثنى عشر في منى، لأن المبيت في منى ليلة إحدى عشرة، واثنى عشرة واجب إذا قدر، إذا استطاع أن يبيت في منى؛ وجب عليه في ليلة الحادي عشر، والثاني عشر، ويجب عليه أن يرمي الجمار الحادي عشر، والثاني عشر، ثم الوداع بعد ذلك. فإذا ترك واحدًا من هذا: ما بات ليلتين، أو ما رمى الجمار يوم الثاني عشر، أو وادع قبل رمي الجمار في الثاني عشر، أو خرج ولم يوادع؛ فعليه عن كل واحدة دم، عن طواف الوداع دم إذا تركه، وعن ترك الرمي يوم الثاني عشر دم، وعن ترك المبيت في ليلتي إحدى عشرة، واثنى عشرة دم، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15254/حكم-تعجل-الحاج-وسفره-في-يوم-الحادي-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_583/58309.mp3","categories":["رمي الجمار"]},{"id":16931,"question":"ما حكم من رمى الجمرات صباحًا في اليوم الحادي عشر، والثاني عشر؟","title":"حكم رمي الجمرات صباحًا","answer":"الجواب: لا يجوز، ولا يصح، الرمي يكون بعد الزوال في أيام التشريق؛ لأن الرسول ﷺ رمى بعد الزوال، وقال: خذوا عني مناسككم فمن رمى قبل الزوال فرميه غير صحيح، فعليه أن يعيده بعد الزوال، فإن فاتت أيام منى، ولم يعد؛ فعليه دم عن ترك هذا الواجب، يذبح في مكة للفقراء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15724/حكم-رمي-الجمرات-صباحا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_827/nour_82705.mp3","categories":["رمي الجمار"]},{"id":16933,"question":"ما حكم من رمى الجمرات جميعًا في اليوم الثاني عشر؟","title":"حكم رمي الجمرات جميعًا في يوم الثاني عشر","answer":"الجواب: إذا رتبها أجزأت عند جمع من أهل العلم، إذا رمى جمرة العقبة، ثم رمى اليوم الأول الجمرات الثلاث، ثم عاد ورماها عن اليوم الثاني، ثم عاد ورماها عن اليوم الثالث أجزأ، لكنه ترك السنة، السنة أن يفعلها في وقتها. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15725/حكم-رمي-الجمرات-جميعا-في-يوم-الثاني-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_827/nour_82706.mp3","categories":["رمي الجمار"]},{"id":17778,"question":"في رمي الجمار الثلاث كنت أرمي الأولى ثم أذهب إلى الثانية مباشرة وكذلك الثالثة ولم أقف وأدعو بعد الأولى والثانية لعدم علمي؟","title":"حكم ترك الدعاء بعد رمي الجمرات","answer":"الجواب: لا حرج في ذلك الوقوف بعد الأولى والثانية للدعاء سنة، ومن تركه فلا شيء عليه، والحمد لله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16766/حكم-ترك-الدعاء-بعد-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77807.mp3","categories":["رمي الجمار"]},{"id":17781,"question":"يقول السائل أبو عبد الله في ثاني أسئلته: في رمي الجمار كنت أكبر مع كل حصاة في البداية ولكن لخوفي من عدم ضبط العدد كنت أعد مع كل حصاة ونسيت التكبير وكنت أرمي عن نفسي وعن موكلتي، فما الحكم في ذلك؟","title":"حكم نسيان التكبير عند الرمي","answer":"الجواب: التكبير مستحب وليس بلازم، إن كبرت فهو الأفضل، وإلا ما يضر الرمي صحيح، إذا رميت عن نفسك ثم رميت عن موكلتك فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/16764/حكم-نسيان-التكبير-عند-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_778/nour_77806.mp3","categories":["رمي الجمار"]},{"id":17996,"question":"الأخت المستمعة حصة عبد الله بعثت برسالة من حوطة بني تميم تقول فيها: أخبركم أنني أديت فريضة الحج في عام من الأعوام ولله الحمد وذلك بيسر وسهولة، ولكن خوفًا من المشقة والزحام وكلت أبي برمي الجمرات في اليوم الثاني عشر ما حكم ما فعلت؟","title":"حكم التوكيل في رمي الجمار","answer":"الجواب: إذا كان ذلك من أجل الزحام والزحام موجود فلا حرج إن شاء الله؛ لأنه عذر شرعي، والمرأة على خطر في الزحام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17014/حكم-التوكيل-في-رمي-الجمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_849/nour_84902.mp3","categories":["رمي الجمار"]},{"id":18170,"question":"يقول: نويت الحج في اليوم الثامن من منى، ووقفت بعرفة، وقمت بالمبيت بمزدلفة، ولكن بعد صلاة الفجر تحركنا بالسيارة إلى خارج مزدلفة، وقمنا برمي جمرة العقبة قبل طلوع الشمس، وقمت بحلق شعري، وبعدها تحللت من الإحرام، وانتظرت حتى بعد صلاة العصر، واتجهت للحرم للطواف، فهل عليّ شيء فيما تقدم؟","title":"حكم رمي جمرة العقبة قبل طلوع الشمس يوم النحر","answer":"الجواب: ليس عليك شيء، ولا على أصحابك، لكن لو أجلتم الرمي إلى بعد طلوع الشمس، يكون أفضل، وإلا فهو مجزي، والحمد لله، من حين .. من الليل ليلة النحر وهو مجزي، لكن الأفضل للأقوياء أن يؤجلوا الرمي إلى بعد طلوع الشمس، كما رمى النبي ﷺ، ومن رمى قبل ذلك؛ أجزأه، ولاسيما الضعفاء من النساء، والشيوخ، والمرضى، كل هذا لا بأس به. أما الأقوياء فالأفضل لهم أن يؤجلوا الرمي إلى بعد ارتفاع الشمس، يوم العيد، هذا هو الأفضل، ومن قدمه فلا حرج، إن شاء الله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17210/حكم-رمي-جمرة-العقبة-قبل-طلوع-الشمس-يوم-النحر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73106.mp3","categories":["رمي الجمار"]},{"id":18171,"question":"يقول: في اليوم الثاني عشر قمت برمي الجمرة الصغرى، قبل صلاة الظهر بحوالي خمس، أو عشر دقائق، ثم تابعت بعد ذلك رمي الوسطى، ثم الكبرى، فهل علي شيء؟","title":"وقت الرمي في أيام التشريق الثلاثة","answer":"الجواب: لابد أن يكون الرمي بعد الزوال، بعد الزوال، ولو قبل الصلاة، كان النبي ﷺ يرمي في الحادي عشر، والثاني عشر، والثالث عشر بعد الزوال وقبل الصلاة، فإذا كان رميك صادف بعد الزوال فلا شيء عليك، أما إن كان رميك قبل الزوال، فعليك دم عما مضى، يذبح في مكة للفقراء؛ لأن الواجب أن يكون الرمي بعد الزوال، في اليوم الحادي عشر، والثاني عشر، وهكذا في الثالث عشر لمن لم يتعجل، فمن رمى قبل الزوال فعليه دم يذبح في مكة للفقراء، في الأيام الثلاثة، الحادي عشر، والثاني عشر، والثالث عشر. نعم. المقدم: جزاكم الله خيرًا، إذًا ماذا عليه والحال ما ذكر -سماحة الشيخ- يقول: إنه رمى قبل الأذان بخمس، أو عشر دقائق؟ الشيخ:  قبل الصلاة يقول، نحن فصلنا له، إن كان قبل الصلاة وبعد الزوال فلا بأس، وإن كان قبل الزوال فعليه دم، إلا إذا كان في وقت بعيد بعد الزوال، لكن اللي مضت، السنوات اللي مضت، عليه دم، إذا كان الرمي قبل الزوال، ولو كان قبل الصلاة ..... المقدم: هنا يقول: قبل الصلاة؛ لكن لا أدري هل يقصد الأذان، أو الصلاة. الشيخ: فيه تفصيل: إن كان بعد الزوال وقبل الصلاة، فقد وافق السنة، أما إن كان قبل الزوال، فقد خالف السنة، وعليه دم. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17211/وقت-الرمي-في-ايام-التشريق-الثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73107.mp3","categories":["رمي الجمار"]},{"id":18822,"question":"في ثاني أيام التشريق يؤذن الظهر في الثانية عشرة والدقيقة الخامسة والعشرين، وقد قمت برمي الجمرة الأولى في الثانية عشرة والدقيقة الثانية والعشرين، أي: قبل الأذان بثلاث دقائق، فهل يجزئ ذلك؟","title":"حكم رمي الجمرات قبل أذان الظهر بدقائق","answer":"الجواب: إذا كانت زالت الشمس ولو ما أذن، إذا كانت الشمس مالت إلى جهة الغرب؛ أجزأ ذلك ولو ما سمعت الأذان، المهم الزوال، فإذا كنت رميت بعد الزوال فالحمد لله، وإلا فعليك دم، عن رميك قبل الزوال، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17951/حكم-رمي-الجمرات-قبل-اذان-الظهر-بدقاىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73604.mp3","categories":["رمي الجمار"]},{"id":18929,"question":"من أسئلة هذا السائل يقول يا سماحة الشيخ: ما حكم رمي الجمرة الكبرى في العمود الخرساني من الخلف؟ وإذا لم تقع الجمار في الحوض، فما الحكم؟","title":"حكم رمي الجمار دون أن تقع في الحوض","answer":"الجواب: لا بد أن تقع الجمار في الحوض، وإذا رمى جمرة العقبة من الخلف، ولم تقع في الحوض ما يجزئ، يكون ما رماها حتى يقع الحصى في الحوض. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18068/حكم-رمي-الجمار-دون-ان-تقع-في-الحوض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88206.mp3","categories":["رمي الجمار"]},{"id":18955,"question":"يقول: إذا رمى الحاج يوم العاشر خطأ إلى اليوم الثاني عشر، هل أعيد وأنا لابس للإحرام أم بثوبي؟","title":"حكم من أخطأ الرمي يوم العيد إلى اليوم الثاني عشر","answer":"الجواب: إذا ما أجزأ رمي يوم العيد يعيد الرمي كله، يعيد رمي العيد ثم ما بعده، وإذا كان قد حلق وطاف طواف الإفاضة وسعى فقد حل، يعيد ولو عليه ملابسه المخيطة، إذا كان قد حلق أو قصر وطاف وسعى فقد فعل اثنين من ثلاثة، أما إن كان ما بعد فعل الطواف والسعي يعيد وعليه ملابس الإحرام ثم يعيد الرمي، لكن ما يتحلل بالحلق وحده أو التقصير وحده.","link":"https://binbaz.org.sa/fatwas/18113/حكم-من-اخطا-الرمي-يوم-العيد-الى-اليوم-الثاني-عشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88231.mp3","categories":["رمي الجمار"]},{"id":18957,"question":"يقول: هل يشترط الترتيب بالرمي الصغرى ثم الوسطى؟","title":"حكم الترتيب في رمي الجمرات","answer":"الجواب: نعم، يرمي الصغرى، ثم الوسطى، ثم الأخيرة، التي تلي مكة هي الأخيرة.","link":"https://binbaz.org.sa/fatwas/18111/حكم-الترتيب-في-رمي-الجمرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88230.mp3","categories":["رمي الجمار"]},{"id":18958,"question":"هذا سائل له أسئلة عن الحج، يقول يا سماحة الشيخ: من رمى قبل الزوال ما حكم ذلك؟","title":"حكم من رمى الجمار قبل الزوال","answer":"الجواب: يعيد الرمي، ما يجزيه إلا بعد الزوال في اليوم الحادي عشر والثاني عشر والثالث عشر، أيام منى الثلاثة بعد العيد، إذا رماها قبل الزوال لا يجزي، عليه أن يرمي بعد الزوال أو في الليل.","link":"https://binbaz.org.sa/fatwas/18109/حكم-من-رمى-الجمار-قبل-الزوال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88229.mp3","categories":["رمي الجمار"]},{"id":19249,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين يسأل فيها جمعًا من الأسئلة، يبدو أن باعثة الرسالة إحدى الأخوات المستمعات تقول أم عبادة من المزاحمية، تسأل وتقول: لقد أديت فريضة الحج قبل خمس سنوات، ولكني لم أرم إلا في المرة الأولى أي: رميت ليلة العيد قبل الفجر، حيث أننا خرجنا من مزدلفة بعد منتصف الليل خوفًا من الزحام، ثم إنني رميت الحصيات ولا أعلم هل وقعت في الحوض أم طاشت عنه ولم تقع، وكان وقتها الزحام شديدًا وكنت في ذلك الوقت جاهلة أنه يجب أن تقع الحصيات في الحوض.وتكمل السؤال -لو تكرمتم سماحة الشيخ- فتقول: كما أنني لم أرم في اليوم الثاني والثالث، وإنما وكلت أخي للرمي عني وذلك خوفًا من الزحام فقط، كما أنني كنت جاهلة بأنه على المرأة أن ترمي بنفسها ولا توكل إلا لعجزها عن ذلك، أفيدوني ما الذي يجب علي في رميي للحصيات حينما كنت لا أعلم هل كانت تقع في الحوض أم كانت تطيش عنه؟ وما الذي يجب علي في توكيلي لأخي في الرمي في اليوم الثاني والثالث؟ هل يجب علي فدو أم ماذا؟ جزاكم الله خيرًا.","title":"حكم من وكلت غيرها في الرمي خوفًا من الزحام","answer":"الجواب: عليك عن جميع ذلك ذبيحة واحدة: عن ترك الرمي في اليوم الثاني والثالث وأنت قادرة، وعن رمي اليوم الأول الذي شككت هل وصلت الحجرات إلى الحوض أم لا، فالمقصود: أن عليك دمًا واحدًا ذبيحة جذع من الضأن أو ثني من المعز كالضحية يذبح في مكة للفقراء عن ترك هذا الواجب؛ لأنه لابد من العلم بوقوع الحصى في المرمى أو غلبة الظن بذلك. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم، أين تذبح هذا الهدي؟ الجواب: في مكة، للفقراء. نعم. المقدم: بارك الله فيكم وأحسن إليكم، إن لم تكن في مكة توكل سماحة الشيخ؟ الجواب: نعم، بنفسها أو بوكيلها. نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18442/حكم-من-وكلت-غيرها-في-الرمي-خوفا-من-الزحام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73812.mp3","categories":["رمي الجمار"]},{"id":19256,"question":"يقول: بعد رمي جمرة العقبة في أول يوم العيد مرضت بالأنفلونزا وجلست لليوم الثاني ورميت الجمرات الثلاث، ثم وكلت شخصًا لرمي جمرات اليوم الثالث، اليوم الثاني من أيام التشريق، وذهبت لطواف الوداع وذهبت إلى جدة عند أخي، فما كان منه إلا أن جعلني أرجع، وقال: هذا لا يجوز، فعدت الساعة الثانية صباحًا -أي بعد منتصف الليل- ورميت في الظهر الجمرات الثلاث ورجعت بعد طواف الوداع للمرة الثانية، أرجو من سماحتكم بيان ما عملت هل هو صحيح؟ جزاكم الله خيرًا.","title":"حكم من وكَّل غيره في رمي الجمار","answer":"الجواب: إذا كان توكيلك لأنك عاجز مريض عاجز عن الرمي فالوكالة صحيحة وليس عليك إعادة وطواف الوداع صحيح إذا كان بعد رمي الوكيل، أما إذا كنت تساهلت في الوكالة وإلا فأنت فعلن تستطيع؛ فالذي أمرك بالرجوع قد أصاب، وعليك أن ترمي الجمار عن اليوم الثاني عشر الذي وكلت فيه، وأن ترمي أيضًا جمار اليوم الثالث عشر؛ لأنك جئت في الليل وأنت يلزمك أن تبقى حتى ترمي الجمرة اليوم الثالث؛ لأنك مضى عليك النهار الثاني وأنت لم ترم الجمرات، وجئت في الليل ليلة ثلاثة عشر، فكان يجب عليك أن تبقى حتى ترمي في اليوم الثالث عشر، فعليك أن تذبح ذبيحة عن عدم مبيتك وعدم رميك في اليوم الثالث عشر. أما الوداع فهذا محل نظر، إن كان الوداع الأول صادف أنك بعد رمي الجمار الأولى وأنت معذور بك مرض، فالوداع صحيح وعودتك ما تضر، أما إن كنت وكلت وأنت لست بحاجة إلى الوكالة أنت صحيح تقوى على الرمي؛ فعليك دم عن ترك الوداع، ودم عن ترك الرمي يوم الثالث عشر، دمان: أحدهما عن ترك الرمي يوم الثالث عشر، والثاني عن ترك الوداع؛ لأنك وادعت قبل أن يحل الوداع؛ لأن الوداع يكون بعد الرمي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18449/حكم-من-وكل-غيره-في-رمي-الجمار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73902.mp3","categories":["رمي الجمار"]},{"id":19709,"question":"رجل حاج كبير السن لما أراد يرمي الجمار وكّل رجلاً ما أتى حاجًّا إنما أتى للعمل مع الدولة في الشرطة أو في غيرها؟","title":"هل يجوز توكيل شخص لم يأت حاجًّا في الرمي؟","answer":"لا، لا بد يكون حاجًّا، الوكيل لا بدّ يكون من الحجاج.","link":"https://binbaz.org.sa/fatwas/27024/هل-يجوز-توكيل-شخص-لم-يات-حاجا-في-الرمي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/%D9%87%D9%84%20%D9%8A%D8%AC%D9%88%D8%B2%20%D8%AA%D9%88%D9%83%D9%8A%D9%84%20%D8%B4%D8%AE%D8%B5%20%D9%84%D9%85%20%D9%8A%D8%A3%D8%AA%20%D8%AD%D8%A7%D8%AC%D9%91%D9%8B%D8%A7%20%D9%81%D9%8A%20%D8%A7%D9%84%D8%B1%D9%85%D9%8A.mp3","categories":["رمي الجمار","النيابة في الحج"]}]
